393→static void PerformSync(
394→    AutomergeDocument doc1,
395→    AutomergeDocument doc2,
396→    AutomergeSyncState state1,
397→    AutomergeSyncState state2,
398→    int maxRounds = 10)
399→{
400→    for (int i = 0; i < maxRounds; i++)
401→    {
402→        var msg1 = doc1.GenerateSyncMessage(state1);
403→        var msg2 = doc2.GenerateSyncMessage(state2);
404→
405→        if (msg1 == null && msg2 == null)
406→        {
407→            break;
408→        }
409→
410→        if (msg1 != null)
411→        {
412→            doc2.ReceiveSyncMessage(state2, msg1);
413→        }
414→
415→        if (msg2 != null)
416→        {
417→            doc1.ReceiveSyncMessage(state1, msg2);
418→        }
419→    }
420→}
