   1→using System.Collections.ObjectModel;
   2→using Ray.Automerge;
   3→using Ray.Automerge.Repository.Network;
   4→using Ray.Automerge.Repository.Storage;
   5→using Ray.Automerge.Repository.Synchronizer;
   6→
   7→namespace Ray.Automerge.Repository;
   8→
   9→/// <summary>
  10→/// Central repository for managing Automerge documents with persistence and sync.
  11→/// </summary>
  12→/// <remarks>
  13→/// <para>
  14→/// The Repo is the main entry point of this library. To construct a Repo you will need
  15→/// an IStorageAdapter and one or more INetworkAdapters. Once you have a Repo you can
  16→/// use it to obtain DocHandles.
  17→/// </para>
  18→/// <para>
  19→/// This is a C# port of the TypeScript automerge-repo Repo class, maintaining API compatibility.
  20→/// </para>
  21→/// </remarks>
  22→[PublicAPI]
  23→public sealed class Repo : IDisposable
  24→{
  25→  // Subsystems
  26→  readonly StorageSubsystem? _storage;
  27→  readonly NetworkSubsystem _network;
  28→  readonly CollectionSynchronizer _synchronizer;
  29→
  30→  // Configuration
  31→  readonly PeerId _peerId;
  32→  readonly bool _isEphemeral;
  33→  readonly int _saveDebounceRate;
  34→  readonly ShareConfig _shareConfig;
  35→  readonly Func<IReadOnlyList<string>, Task<byte[]>>? _idFactory;
  36→
  37→  // Handle management
  38→  readonly Dictionary<string, IDocHandle> _handleCache = [];
  39→  readonly Dictionary<string, Task<IDocHandle>> _findInProgress = [];
  40→  readonly SemaphoreSlim _handleLock = new(1, 1);
  41→
  42→  // Save throttling
  43→  readonly Dictionary<string, CancellationTokenSource> _pendingSaves = [];
  44→  readonly SemaphoreSlim _saveLock = new(1, 1);
  45→
  46→  bool _isDisposed;
  47→
  48→
  49→  #region Events
  50→
  51→  /// <summary>
  52→  /// Raised when a document is loaded and ready.
  53→  /// </summary>
  54→  public event EventHandler<DocumentEventArgs>? DocumentLoaded;
  55→
  56→  /// <summary>
  57→  /// Raised when a document is deleted.
  58→  /// </summary>
  59→  public event EventHandler<DocumentDeletedEventArgs>? DocumentDeleted;
  60→
  61→  /// <summary>
  62→  /// Raised when a document is unavailable from all peers.
  63→  /// </summary>
  64→  public event EventHandler<DocumentUnavailableEventArgs>? DocumentUnavailable;
  65→
  66→  /// <summary>
  67→  /// Raised when a peer connects.
  68→  /// </summary>
  69→  public event EventHandler<PeerEventArgs>? PeerConnected;
  70→
  71→  /// <summary>
  72→  /// Raised when a peer disconnects.
  73→  /// </summary>
  74→  public event EventHandler<PeerEventArgs>? PeerDisconnected;
  75→
  76→  #endregion
  77→
  78→  #region Properties
  79→
  80→  /// <summary>
  81→  /// Gets the peer ID of this repository.
  82→  /// </summary>
  83→  public PeerId PeerId => _peerId;
  84→
  85→  /// <summary>
  86→  /// Gets the list of currently connected peers.
  87→  /// </summary>
  88→  public IReadOnlyList<PeerId> Peers => _network.Peers;
  89→
  90→  /// <summary>
  91→  /// Gets a read-only snapshot of all cached handles.
  92→  /// </summary>
  93→  public IReadOnlyDictionary<string, IDocHandle> Handles
  94→  {
  95→    get
  96→    {
  97→      _handleLock.Wait();
  98→      try
  99→      {
 100→        return new ReadOnlyDictionary<string, IDocHandle>(
 101→          new Dictionary<string, IDocHandle>(_handleCache));
 102→      }
 103→      finally
 104→      {
 105→        _handleLock.Release();
 106→      }
 107→    }
 108→  }
 109→
 110→  #endregion
 111→
 112→
 113→  /// <summary>
 114→  /// Initializes a new repository with the specified configuration.
 115→  /// </summary>
 116→  /// <param name="config">Configuration for the repository.</param>
 117→  /// <exception cref="ArgumentNullException">Thrown if config is null.</exception>
 118→  public Repo(RepoConfig config)
 119→  {
 120→    if(config is null)
 121→      throw new ArgumentNullException(nameof(config));
 122→
 123→    // Initialize identity
 124→    _peerId = config.PeerId ?? PeerId.Generate();
 125→    _isEphemeral = config.IsEphemeral;
 126→    _saveDebounceRate = config.SaveDebounceRate;
 127→    _shareConfig = config.ShareConfig ?? ShareConfig.AllowAll;
 128→    _idFactory = config.IdFactory;
 129→
 130→    // Initialize storage subsystem
 131→    if(config.Storage is not null)
 132→    {
 133→      _storage = new StorageSubsystem(config.Storage);
 134→      _storage.DocumentLoaded += OnStorageDocumentLoaded;
 135→      _storage.DocumentSaved += OnStorageDocumentSaved;
 136→    }
 137→
 138→    // Initialize network subsystem
 139→    _network = new NetworkSubsystem(config.NetworkAdapters);
 140→    _network.PeerCandidate += OnNetworkPeerCandidate;
 141→    _network.PeerDisconnected += OnNetworkPeerDisconnected;
 142→    _network.MessageReceived += OnNetworkMessageReceived;
 143→
 144→    // Initialize synchronizer
 145→    _synchronizer = new CollectionSynchronizer(
 146→      GetDocument,
 147→      UpdateDocument,
 148→      GetPeerMetadata,
 149→      RequestDocument,
 150→      config.Denylist);
 151→
 152→    _synchronizer.MessageToSend += OnSynchronizerMessage;
 153→    _synchronizer.SyncStateChanged += OnSynchronizerSyncStateChanged;
 154→    _synchronizer.DocumentUnavailable += OnSynchronizerDocumentUnavailable;
 155→
 156→    // Set share and access policies
 157→    if(_shareConfig.Announce is not null)
 158→    {
 159→      _synchronizer.SetSharePolicy(AdaptAnnouncePolicy);
 160→    }
 161→
 162→    if(_shareConfig.Access is not null)
 163→    {
 164→      _synchronizer.SetAccessPolicy(AdaptAccessPolicy);
 165→    }
 166→  }
 167→  
 168→  
 169→  /// <summary>
 170→  /// Disposes the repository and releases all resources.
 171→  /// </summary>
 172→  public void Dispose()
 173→  {
 174→    if(_isDisposed) return;
 175→
 176→    _isDisposed = true;
 177→
 178→    // Cancel all pending saves
 179→    _saveLock.Wait();
 180→    try
 181→    {
 182→      foreach(var cts in _pendingSaves.Values)
 183→      {
 184→        cts.Cancel();
 185→        cts.Dispose();
 186→      }
 187→
 188→      _pendingSaves.Clear();
 189→    }
 190→    finally
 191→    {
 192→      _saveLock.Release();
 193→    }
 194→
 195→    // Dispose synchronizer
 196→    _synchronizer.Dispose();
 197→
 198→    // Dispose network subsystem
 199→    _network.Dispose();
 200→
 201→    // Dispose storage subsystem
 202→    _storage?.Dispose();
 203→
 204→    // Dispose all handles
 205→
 206→    _handleLock.Wait();
 207→    try
 208→    {
 209→      foreach(var handle in _handleCache.Values)
 210→      {
 211→        handle.Dispose();
 212→      }
 213→
 214→      _handleCache.Clear();
 215→    }
 216→    finally
 217→    {
 218→      _handleLock.Release();
 219→    }
 220→
 221→    // Dispose locks
 222→    _handleLock.Dispose();
 223→    _saveLock.Dispose();
 224→  }
