 229→
 230→  // Policy adapter: Announce(peerId, docId?) → SharePolicy(docId, peerId)
 231→  async Task<bool> AdaptAnnouncePolicy(DocumentId documentId, PeerId peerId)
 232→  {
 233→    if(_shareConfig.Announce is null) return true;
 234→    return await _shareConfig.Announce(peerId, documentId);
 235→  }
 236→
 237→  // Policy adapter: Access(peerId, docId) → AccessPolicy(docId, peerId)
 238→  async Task<bool> AdaptAccessPolicy(DocumentId documentId, PeerId peerId)
 239→  {
 240→    if(_shareConfig.Access is null) return true;
 241→    return await _shareConfig.Access(peerId, documentId);
 242→  }
