 245→  #region Document Lifecycle - Create
 246→
 247→  /// <summary>
 248→  /// Creates a new document with optional initial value.
 249→  /// Mirrors TypeScript's synchronous Repo.create() method.
 250→  /// Uses default document ID generation (not the idFactory).
 251→  /// For custom ID generation via idFactory, use CreateAsync{T}().
 252→  /// </summary>
 253→  /// <typeparam name="T">The document content type.</typeparam>
 254→  /// <param name="initialValue">Optional initial value for the document.</param>
 255→  /// <returns>A handle to the newly created document.</returns>
 256→  public DocHandle<T> Create<T>(T? initialValue = default)
 257→  {
 258→    ThrowIfDisposed();
 259→
 260→    // Generate document ID using default generator (not idFactory)
 261→    // idFactory is async, so it's handled in CreateAsync() instead
 262→    var documentId = DocumentId.Generate();
 263→
 264→    // Validate document ID
 265→    if(!DocumentId.IsValid(documentId))
 266→    {
 267→      throw new ArgumentException($"Invalid document ID: {documentId}");
 268→    }
 269→
 270→    _handleLock.Wait();
 271→    try
 272→    {
 273→      // Check if already exists
 274→      if(_handleCache.ContainsKey(documentId))
 275→      {
 276→        throw new InvalidOperationException($"Document already exists: {documentId}");
 277→      }
 278→
 279→      // Create document
 280→      var doc = AutomergeDocument.Create();
 281→
 282→      // Create handle
 283→      var handle = new DocHandle<T>(
 284→        documentId,
 285→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 286→        doc);
 287→
 288→      // Cache handle
 289→      _handleCache[documentId] = handle;
 290→
 291→      // Register with subsystems
 292→      RegisterHandle(documentId, handle);
 293→
 294→      // Emit event
 295→      DocumentLoaded?.Invoke(this,
 296→        new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 297→
 298→      return handle;
 299→    }
 300→    finally
 301→    {
 302→      _handleLock.Release();
 303→    }
 304→  }
 305→
 306→  /// <summary>
 307→  /// Creates a new document asynchronously with optional initial value.
 308→  /// Uses idFactory for document ID generation if configured.
 309→  /// This mirrors TypeScript's experimental Repo.create2() method.
 310→  /// </summary>
 311→  /// <typeparam name="T">The document content type.</typeparam>
 312→  /// <param name="initialValue">Optional initial value for the document.</param>
 313→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 314→  public async Task<DocHandle<T>> CreateAsync<T>(T? initialValue = default)
 315→  {
 316→    ThrowIfDisposed();
 317→
 318→    // Generate document ID
 319→    DocumentId documentId;
 320→    if(_idFactory is not null)
 321→    {
 322→      // Use idFactory for ID generation
 323→      var initialDoc = AutomergeDocument.Create();
 324→      var heads = initialDoc.GetHeads();
 325→      var binaryId = await _idFactory(heads).ConfigureAwait(false);
 326→      documentId = DocumentId.FromBinary(binaryId);
 327→    }
 328→    else
 329→    {
 330→      // Fall back to default ID generation
 331→      documentId = DocumentId.Generate();
 332→    }
 333→
 334→    // Validate document ID
 335→    if(!DocumentId.IsValid(documentId))
 336→    {
 337→      throw new ArgumentException($"Invalid document ID: {documentId}");
 338→    }
 339→
 340→    await _handleLock.WaitAsync().ConfigureAwait(false);
 341→    try
 342→    {
 343→      // Check if already exists
 344→      if(_handleCache.ContainsKey(documentId))
 345→      {
 346→        throw new InvalidOperationException($"Document already exists: {documentId}");
 347→      }
 348→
 349→      // Create document
 350→      var doc = AutomergeDocument.Create();
 351→
 352→      // Create handle
 353→      var handle = new DocHandle<T>(
 354→        documentId,
 355→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 356→        doc);
 357→
 358→      // Cache handle
 359→      _handleCache[documentId] = handle;
 360→
 361→      // Register with subsystems
 362→      RegisterHandle(documentId, handle);
 363→
 364→      // Emit event
 365→      DocumentLoaded?.Invoke(this,
 366→        new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 367→
 368→      return handle;
 369→    }
 370→    finally
 371→    {
 372→      _handleLock.Release();
 373→    }
 374→  }
 375→
 376→  /// <summary>
 377→  /// Creates a new document with a specific document ID and optional initial value.
 378→  /// </summary>
 379→  /// <typeparam name="T">The document content type.</typeparam>
 380→  /// <param name="documentId">The document ID to use for the new document.</param>
 381→  /// <param name="initialValue">Optional initial value for the document.</param>
 382→  /// <returns>A handle to the newly created document.</returns>
 383→  /// <exception cref="ArgumentException">Thrown if document ID is invalid.</exception>
 384→  /// <exception cref="InvalidOperationException">Thrown if a document with this ID already exists.</exception>
 385→  public DocHandle<T> Create<T>(string documentId, T? initialValue = default)
 386→  {
 387→    ThrowIfDisposed();
 388→
 389→    if(string.IsNullOrWhiteSpace(documentId))
 390→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 391→
 392→    // Validate document ID
 393→    if(!DocumentId.IsValid(documentId))
 394→    {
 395→      throw new ArgumentException($"Invalid document ID: {documentId}");
 396→    }
 397→
 398→    var documentIdValue = DocumentId.Parse(documentId);
 399→
 400→    _handleLock.Wait();
 401→    try
 402→    {
 403→      // Check if already exists
 404→      if(_handleCache.ContainsKey(documentId))
 405→      {
 406→        throw new InvalidOperationException($"Document already exists: {documentId}");
 407→      }
 408→
 409→      // Create document
 410→      var doc = AutomergeDocument.Create();
 411→
 412→      // Create handle
 413→      var handle = new DocHandle<T>(
 414→        documentId,
 415→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 416→        doc);
 417→
 418→      // Cache handle
 419→      _handleCache[documentId] = handle;
 420→
 421→      // Register with subsystems
 422→      RegisterHandle(documentId, handle);
 423→
 424→      // Emit event
 425→      DocumentLoaded?.Invoke(this,
 426→        new DocumentEventArgs { DocumentId = documentIdValue, Handle = handle });
 427→
 428→      return handle;
 429→    }
 430→    finally
 431→    {
 432→      _handleLock.Release();
 433→    }
 434→  }
 435→
 436→  #endregion
 437→
 438→  #region Document Lifecycle - Find
 439→
 440→  /// <summary>
 441→  /// Finds an existing document, loading from storage or requesting from network.
 442→  /// </summary>
 443→  /// <typeparam name="T">The document content type.</typeparam>
 444→  /// <param name="documentId">The document ID to find.</param>
 445→  /// <param name="timeout">Optional timeout for loading. Default: 10 seconds.</param>
 446→  /// <returns>
 447→  /// A <see cref="DocHandle{T}"/> if the document exists or was loaded successfully, or null if the document
 448→  /// does not exist and could not be loaded from the network within the timeout period.
 449→  /// </returns>
 450→  /// <exception cref="ArgumentException">Thrown if document ID is invalid.</exception>
 451→  public async Task<DocHandle<T>?> Find<T>(string documentId, TimeSpan? timeout = null)
 452→  {
 453→    if(string.IsNullOrWhiteSpace(documentId))
 454→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 455→
 456→    if(!DocumentId.IsValid(documentId))
 457→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 458→
 459→    var documentIdValue = DocumentId.Parse(documentId);
 460→
 461→    ThrowIfDisposed();
 462→
 463→    timeout ??= TimeSpan.FromSeconds(10);
 464→
 465→    await _handleLock.WaitAsync();
 466→    Task<IDocHandle>? findTask;
 467→    try
 468→    {
 469→      // Check cache first
 470→      if(_handleCache.TryGetValue(documentId, out var cachedHandle))
 471→      {
 472→        return (DocHandle<T>)cachedHandle;
 473→      }
 474→
 475→      // Check if find already in progress
 476→      if(_findInProgress.TryGetValue(documentId, out findTask))
 477→      {
 478→        // Wait for existing find operation
 479→        _handleLock.Release();
 480→        var result = await findTask;
 481→        return (DocHandle<T>)result;
 482→      }
 483→
 484→      // Start new find operation
 485→      var tcs = new TaskCompletionSource<IDocHandle>();
 486→      _findInProgress[documentId] = tcs.Task;
 487→      findTask = tcs.Task;
 488→    }
 489→    finally
 490→    {
 491→      if(_handleLock.CurrentCount == 0)
 492→        _handleLock.Release();
 493→    }
 494→
 495→    try
 496→    {
 497→      // Attempt to load from storage first
 498→      AutomergeDocument? doc = null;
 499→      if(_storage is not null)
 500→      {
 501→        doc = await _storage.LoadDoc(documentId);
 502→      }
 503→
 504→      // Create handle (without document - we'll initialize explicitly)
 505→      var handle = new DocHandle<T>(
 506→        documentId,
 507→        new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>(), Timeout = timeout.Value },
 508→        document: null);
 509→
 510→      // Cache handle
 511→      await _handleLock.WaitAsync();
 512→      try
 513→      {
 514→        _handleCache[documentId] = handle;
 515→        _findInProgress.Remove(documentId);
 516→
 517→        // Complete the TaskCompletionSource
 518→        if(findTask is Task<IDocHandle> task &&
 519→           task.AsyncState is TaskCompletionSource<IDocHandle> taskSource)
 520→        {
 521→          taskSource.SetResult(handle);
 522→        }
 523→      }
 524→      finally
 525→      {
 526→        _handleLock.Release();
 527→      }
 528→
 529→      // Begin lifecycle: Idle → Loading
 530→      handle.Begin();
 531→
 532→      // Split into two paths based on whether a document was loaded from storage
 533→      if(doc is not null)
 534→      {
 535→        // PATH A: Document found in storage
 536→        // Initialize the handle with the loaded document
 537→        handle.Initialize(doc, isNewDocument: false);
 538→        handle.DoneLoading();  // Loading → Ready
 539→
 540→        // Now register with subsystems
 541→        RegisterHandle(documentId, handle);
 542→
 543→        // Emit loaded event
 544→        DocumentLoaded?.Invoke(this,
 545→          new DocumentEventArgs { DocumentId = documentIdValue, Handle = handle });
 546→
 547→        return handle;  // Already ready, return immediately
 548→      }
 549→      else
 550→      {
 551→        // PATH B: Document must be loaded from network (or created if unavailable)
 552→        // Wait for network to be ready before requesting
 553→        await _network.WhenReady();
 554→
 555→        // Transition to requesting state: Loading → Requesting
 556→        handle.Request();
 557→
 558→        // Now register with subsystems (synchronizer sees Requesting state)
 559→        RegisterHandle(documentId, handle);
 560→
 561→        // Wait for the handle to be ready (or timeout)
 562→        using var cts = new CancellationTokenSource(timeout.Value);
 563→        try
 564→        {
 565→          await handle.WhenReadyAsync(cts.Token);
 566→          return handle;  // Document loaded successfully from network
 567→        }
 568→        catch(OperationCanceledException)
 569→        {
 570→          // Timeout: document not available from network
 571→          // Return null to indicate document doesn't exist
 572→          // Caller should use Create() to create a new document
 573→          return null;
 574→        }
 575→      }
 576→    }
 577→    catch(Exception)
 578→    {
 579→      // Clean up on error
 580→      await _handleLock.WaitAsync();
 581→      try
 582→      {
 583→        _findInProgress.Remove(documentId);
 584→      }
 585→      finally
 586→      {
 587→        _handleLock.Release();
 588→      }
 589→
 590→      throw;
 591→    }
 592→  }
 593→
