1033→  /// <summary>
1034→  /// Callback for synchronizer to update document.
1035→  /// </summary>
1036→  void UpdateDocument(string documentId, AutomergeDocument document)
1037→  {
1038→    _handleLock.Wait();
1039→    IDocHandle? handle;
1040→    try
1041→    {
1042→      if(!_handleCache.TryGetValue(documentId, out handle))
1043→      {
1044→        return;
1045→      }
1046→    }
1047→    finally
1048→    {
1049→      _handleLock.Release();
1050→    }
1051→
1052→    // If handle is not initialized (requesting from network), initialize it now
1053→    if(handle.State == HandleState.Requesting || handle.State == HandleState.Loading)
1054→    {
1055→      // Initialize with received document
1056→      handle.Initialize(document, isNewDocument: false);
1057→      handle.DoneLoading();  // Transition to Ready
1058→    }
1059→    else if(handle.State == HandleState.Ready)
1060→    {
1061→      // Handle already initialized - document was updated by sync protocol
1062→      // The document parameter is the SAME instance that's in the handle (updated in-place),
1063→      // but we need to trigger change notifications
1064→      if(handle is DocHandle<AutomergeDocument> docHandle)
1065→      {
1066→        docHandle.NotifyRemoteChange(document);
1067→        Console.WriteLine($"[DocSync] Post-update state for document {documentId}: {document.HydrateJson()}");
1068→      }
1069→    }
