  3→/// <summary>
  4→/// Manages network communication across multiple adapters with message routing and deduplication.
  5→/// </summary>
  6→/// <remarks>
  7→/// <para>NetworkSubsystem provides:</para>
  8→/// <list type="bullet">
  9→/// <item><description>Support for multiple concurrent network adapters</description></item>
 10→/// <item><description>Message routing between adapters and the repo</description></item>
 11→/// <item><description>Ephemeral message deduplication to prevent gossip loops</description></item>
 12→/// <item><description>Peer connection lifecycle management</description></item>
 13→/// <item><description>Peer metadata storage</description></item>
 14→/// </list>
 15→/// <para>Thread Safety: This class is thread-safe. All public methods and properties can be called from any thread.</para>
 16→/// </remarks>
 17→[PublicAPI]
 18→public sealed class NetworkSubsystem : IDisposable
 19→{
 20→  readonly List<INetworkAdapter> _adapters = [];
 21→  readonly Dictionary<PeerId, INetworkAdapter> _peerToAdapter = [];
 22→  readonly Dictionary<string, PeerMetadata> _peerMetadata = [];
 23→  readonly HashSet<string> _seenEphemeralMessages = [];
 24→  readonly SemaphoreSlim _lock = new(1, 1);
 25→  bool _isDisposed;
 26→
 27→
 28→  /// <summary>
 29→  /// Raised when a new peer candidate is discovered by any adapter.
 30→  /// </summary>
 31→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 32→
 33→  /// <summary>
 34→  /// Raised when a peer disconnects from any adapter.
 35→  /// </summary>
 36→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 37→
 38→  /// <summary>
 39→  /// Raised when a message is received from any adapter.
 40→  /// </summary>
 41→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 42→
 43→  /// <summary>
 44→  /// Returns true if at least one adapter is ready.
 45→  /// </summary>
 46→  public bool IsReady
 47→  {
 48→    get
 49→    {
 50→      ThrowIfDisposed();
 51→      _lock.Wait();
 52→      try
 53→      {
 54→        return _adapters.Any(a => a.IsReady);
 55→      }
 56→      finally
 57→      {
 58→        _lock.Release();
 59→      }
 60→    }
 61→  }
 62→
 63→  /// <summary>
 64→  /// Returns all currently connected peers.
 65→  /// </summary>
 66→  public IReadOnlyList<PeerId> Peers
 67→  {
 68→    get
 69→    {
 70→      ThrowIfDisposed();
 71→      _lock.Wait();
 72→      try
 73→      {
 74→        return _peerToAdapter.Keys.ToList();
 75→      }
 76→      finally
 77→      {
 78→        _lock.Release();
 79→      }
 80→    }
 81→  }
 82→
 83→
 84→  /// <summary>
 85→  /// Initializes a new instance of the NetworkSubsystem.
 86→  /// </summary>
 87→  /// <param name="adapters">Optional initial set of network adapters.</param>
 88→  public NetworkSubsystem(IEnumerable<INetworkAdapter>? adapters = null)
 89→  {
 90→    if(adapters is not null)
 91→    {
 92→      foreach(var adapter in adapters)
 93→      {
 94→        AddAdapter(adapter);
 95→      }
 96→    }
 97→  }
 98→
 99→  /// <summary>
100→  /// Disposes the NetworkSubsystem, disconnecting all adapters and releasing resources.
101→  /// </summary>
102→  public void Dispose()
103→  {
104→    if(_isDisposed) return;
105→
106→    _lock.Wait();
107→    try
108→    {
109→      _isDisposed = true;
110→
111→      // Disconnect and unwire all adapters
112→      foreach(var adapter in _adapters.ToList())
113→      {
114→        adapter.PeerCandidate -= OnAdapterPeerCandidate;
115→        adapter.PeerDisconnected -= OnAdapterPeerDisconnected;
116→        adapter.MessageReceived -= OnAdapterMessageReceived;
117→
118→        // Note: We don't call Disconnect() here as that's the responsibility of the adapter owner
119→      }
120→
121→      _adapters.Clear();
122→      _peerToAdapter.Clear();
123→      _peerMetadata.Clear();
124→      _seenEphemeralMessages.Clear();
125→    }
126→    finally
127→    {
128→      _lock.Release();
129→      _lock.Dispose();
130→    }
131→  }
132→
133→  
134→  // PUBLIC METHODS
135→  // ---------------------------------------------------------------------------------------------------------
136→
137→  /// <summary>
138→  /// Adds a network adapter to the subsystem.
139→  /// </summary>
140→  /// <param name="adapter">The adapter to add.</param>
141→  /// <exception cref="ArgumentNullException">Thrown if adapter is null.</exception>
142→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
143→  public void AddAdapter(INetworkAdapter adapter)
144→  {
145→    if(adapter is null) throw new ArgumentNullException(nameof(adapter));
146→    ThrowIfDisposed();
147→
148→    _lock.Wait();
149→    try
150→    {
151→      if(_adapters.Contains(adapter)) return;
152→
153→      _adapters.Add(adapter);
154→
155→      // Wire up events
156→      adapter.PeerCandidate += OnAdapterPeerCandidate;
157→      adapter.PeerDisconnected += OnAdapterPeerDisconnected;
158→      adapter.MessageReceived += OnAdapterMessageReceived;
159→    }
160→    finally
161→    {
162→      _lock.Release();
163→    }
164→  }
165→
166→  /// <summary>
167→  /// Removes a network adapter from the subsystem.
168→  /// </summary>
169→  /// <param name="adapter">The adapter to remove.</param>
170→  /// <exception cref="ArgumentNullException">Thrown if adapter is null.</exception>
171→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
172→  public void RemoveAdapter(INetworkAdapter adapter)
173→  {
174→    if(adapter is null) throw new ArgumentNullException(nameof(adapter));
175→    ThrowIfDisposed();
176→
177→    _lock.Wait();
178→    try
179→    {
180→      if(!_adapters.Remove(adapter)) return;
181→
182→      // Unwire events
183→      adapter.PeerCandidate -= OnAdapterPeerCandidate;
184→      adapter.PeerDisconnected -= OnAdapterPeerDisconnected;
185→      adapter.MessageReceived -= OnAdapterMessageReceived;
186→
187→      // Remove peers associated with this adapter
188→      var peersToRemove = _peerToAdapter
189→        .Where(kvp => kvp.Value == adapter)
190→        .Select(kvp => kvp.Key)
191→        .ToList();
192→
193→      foreach(var peer in peersToRemove)
194→      {
195→        _peerToAdapter.Remove(peer);
196→        _peerMetadata.Remove(peer);
197→      }
198→    }
199→    finally
200→    {
201→      _lock.Release();
202→    }
203→  }
204→
205→  /// <summary>
206→  /// Sends a message through the appropriate adapter(s).
207→  /// For messages with a target peer, sends via that peer's adapter.
208→  /// For broadcast messages, sends via all ready adapters.
209→  /// </summary>
210→  /// <param name="message">The message to send.</param>
211→  /// <exception cref="ArgumentNullException">Thrown if message is null.</exception>
212→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
213→  public void Send(IRepoMessage message)
214→  {
215→    if(message is null) 
216→      throw new ArgumentNullException(nameof(message));
217→    
218→    ThrowIfDisposed();
219→
220→    // Determine target adapter(s)
221→    INetworkAdapter? targetAdapter = null;
222→
223→    // If message has a target peer (in custom metadata), use that adapter
224→    // Otherwise, broadcast to all adapters
225→    // Note: TypeScript uses targetId field, we can add TargetPeerId to IRepoMessage if needed
226→
227→    _lock.Wait();
228→    try
229→    {
230→      if(targetAdapter is not null)
231→      {
232→        // Send to specific adapter
233→        targetAdapter.Send(message);
234→      }
235→      else
236→      {
237→        // Broadcast to all ready adapters
238→        foreach(var adapter in _adapters)
239→        {
240→          if(adapter.IsReady)
241→          {
242→            adapter.Send(message);
243→          }
244→        }
245→      }
246→    }
247→    finally
248→    {
249→      _lock.Release();
250→    }
251→  }
252→
253→  /// <summary>
254→  /// Waits for at least one adapter to be ready.
255→  /// </summary>
256→  /// <returns>A task that completes when at least one adapter is ready.</returns>
257→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
258→  public async Task WhenReady()
259→  {
260→    ThrowIfDisposed();
261→
262→    // Poll adapters until one is ready
263→    while(true)
264→    {
265→      await _lock.WaitAsync();
266→      try
267→      {
268→        if(_adapters.Any(a => a.IsReady))
269→          return;
270→      }
271→      finally
272→      {
273→        _lock.Release();
274→      }
275→
276→      // Wait a bit before checking again
277→      await Task.Delay(100);
278→    }
279→  }
280→
281→  /// <summary>
282→  /// Returns metadata for a peer, if available.
283→  /// </summary>
284→  /// <param name="peerId">The peer ID to look up.</param>
285→  /// <returns>The peer metadata, or null if not found.</returns>
286→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
287→  public PeerMetadata? GetPeerMetadata(PeerId peerId)
288→  {
289→    ThrowIfDisposed();
290→
291→    _lock.Wait();
292→    try
293→    {
294→      return _peerMetadata.TryGetValue(peerId, out var metadata) ? metadata : null;
295→    }
296→    finally
297→    {
298→      _lock.Release();
299→    }
300→  }
301→
302→
303→  // PRIVATE METHODS
304→  // ---------------------------------------------------------------------------------------------------------
305→  void OnAdapterPeerCandidate(object? sender, PeerCandidateEventArgs e)
306→  {
307→    if(sender is not INetworkAdapter adapter) return;
308→
309→    _lock.Wait();
310→    try
311→    {
312→      // Track peer-to-adapter mapping
313→      _peerToAdapter[e.PeerId] = adapter;
314→
315→      // Store peer metadata
316→      if(e.Metadata is not null)
317→      {
318→        _peerMetadata[e.PeerId] = e.Metadata;
319→      }
320→    }
321→    finally
322→    {
323→      _lock.Release();
324→    }
325→
326→    // Forward event to subscribers
327→    PeerCandidate?.Invoke(this, e);
328→  }
329→
330→  void OnAdapterPeerDisconnected(object? sender, PeerDisconnectedEventArgs e)
331→  {
332→    _lock.Wait();
333→    try
334→    {
335→      _peerToAdapter.Remove(e.PeerId);
336→      _peerMetadata.Remove(e.PeerId);
337→    }
338→    finally
339→    {
340→      _lock.Release();
341→    }
342→
343→    // Forward event to subscribers
344→    PeerDisconnected?.Invoke(this, e);
345→  }
346→
347→  void OnAdapterMessageReceived(object? sender, MessageReceivedEventArgs e)
348→  {
349→    var message = e.Message;
350→
351→    // Deduplicate ephemeral messages
352→    if(message is EphemeralMessage ephemeral)
353→    {
354→      if(!ShouldProcessEphemeralMessage(ephemeral))
355→      {
356→        // Already seen this message, skip
357→        return;
358→      }
359→    }
360→
361→    // Forward message to subscribers
362→    MessageReceived?.Invoke(this, e);
363→  }
364→
365→  /// <summary>
366→  /// Checks if ephemeral message should be processed (deduplication).
367→  /// Returns true if message is new, false if already seen.
368→  /// </summary>
369→  bool ShouldProcessEphemeralMessage(EphemeralMessage message)
370→  {
371→    // Create the unique key: peerId:sessionId:count
372→    var key = $"{message.SenderId}:{message.SessionId}:{message.Count}";
373→
374→    _lock.Wait();
375→    try
376→    {
377→      if(!_seenEphemeralMessages.Add(key))
378→        return false; // Already seen
379→
380→      // Add to seen set
381→      // Cleanup old entries periodically (keep last 1000)
382→      if(_seenEphemeralMessages.Count > 1000)
383→      {
384→        // Remove oldest half
385→        var toRemove = _seenEphemeralMessages.Take(500).ToList();
386→        foreach(var item in toRemove)
387→        {
388→          _seenEphemeralMessages.Remove(item);
389→        }
390→      }
391→
392→      return true; // New message
393→    }
394→    finally
395→    {
396→      _lock.Release();
397→    }
398→  }
399→
400→  void ThrowIfDisposed()
401→  {
402→    if(_isDisposed)
403→    {
404→      throw new ObjectDisposedException(nameof(NetworkSubsystem));
405→    }
406→  }
407→}

  1→using Ray.Automerge;
  2→
  3→namespace Ray.Automerge.Repository.Storage;
  4→
  5→/// <summary>
  6→/// Manages document persistence and sync state storage with automatic compaction.
  7→/// </summary>
  8→/// <remarks>
  9→/// <para>
 10→/// The storage subsystem implements an efficient storage strategy:
 11→/// </para>
 12→/// <list type="number">
 13→/// <item>First save: stores full snapshot</item>
 14→/// <item>Subsequent saves: stores incremental changes</item>
 15→/// <item>When incremental size >= snapshot size: compact (new snapshot, remove old chunks)</item>
 16→/// </list>
 17→/// <para>
 18→/// This balances storage size vs. load performance. Loading is always: snapshot + incrementals.
 19→/// </para>
 20→/// </remarks>
 21→[PublicAPI]
 22→public sealed class StorageSubsystem : IDisposable
 23→{
 24→  readonly IStorageAdapter _adapter;
 25→  readonly Dictionary<string, Task> _pendingSaves = [];
 26→  readonly Dictionary<string, IReadOnlyList<string>> _lastSavedHeads = [];
 27→  readonly SemaphoreSlim _saveLock = new(1, 1);
 28→  bool _isDisposed;
 29→  
 30→  
 31→  
 32→  /// <summary>
 33→  /// Event raised when a document is successfully loaded from storage.
 34→  /// </summary>
 35→  public event EventHandler<DocumentLoadedEventArgs>? DocumentLoaded;
 36→
 37→  /// <summary>
 38→  /// Event raised when a document is successfully saved to storage.
 39→  /// </summary>
 40→  public event EventHandler<DocumentSavedEventArgs>? DocumentSaved;
 41→  
 42→  
 43→
 44→  /// <summary>
 45→  /// Initializes a new instance of <see cref="StorageSubsystem"/> with the specified storage adapter.
 46→  /// </summary>
 47→  /// <param name="adapter">The storage adapter to use for persistence.</param>
 48→  /// <exception cref="ArgumentNullException">Thrown if adapter is null.</exception>
 49→  public StorageSubsystem(IStorageAdapter adapter)
 50→  {
 51→    _adapter = adapter ?? throw new ArgumentNullException(nameof(adapter));
 52→  }
 53→  
 54→  /// <summary>
 55→  /// Disposes this storage subsystem and releases resources.
 56→  /// </summary>
 57→  public void Dispose()
 58→  {
 59→    if(_isDisposed)
 60→      return;
 61→
 62→    _isDisposed = true;
 63→    _saveLock.Dispose();
 64→  }
 65→  
 66→  
 67→
 68→  /// <summary>
 69→  /// Loads data from a generic namespace/key pair.
 70→  /// </summary>
 71→  /// <param name="namespace">The namespace for organizing keys.</param>
 72→  /// <param name="key">The key within the namespace.</param>
 73→  /// <returns>The data if found; null otherwise.</returns>
 74→  /// <exception cref="ArgumentException">Thrown if namespace or key is null or whitespace.</exception>
 75→  public async Task<byte[]?> Load(string @namespace, string key)
 76→  {
 77→    ThrowIfDisposed();
 78→
 79→    if(string.IsNullOrWhiteSpace(@namespace))
 80→      throw new ArgumentException("Namespace cannot be null or whitespace.", nameof(@namespace));
 81→    if(string.IsNullOrWhiteSpace(key))
 82→      throw new ArgumentException("Key cannot be null or whitespace.", nameof(key));
 83→
 84→    var storageKey = StorageKey.Generic(@namespace, key);
 85→    return await _adapter.Load(storageKey);
 86→  }
 87→
 88→  /// <summary>
 89→  /// Saves data to a generic namespace/key pair.
 90→  /// </summary>
 91→  /// <param name="namespace">The namespace for organizing keys.</param>
 92→  /// <param name="key">The key within the namespace.</param>
 93→  /// <param name="data">The data to save.</param>
 94→  /// <exception cref="ArgumentException">Thrown if namespace or key is null or whitespace.</exception>
 95→  /// <exception cref="ArgumentNullException">Thrown if data is null.</exception>
 96→  public async Task Save(string @namespace, string key, byte[] data)
 97→  {
 98→    ThrowIfDisposed();
 99→
100→    if(string.IsNullOrWhiteSpace(@namespace))
101→      throw new ArgumentException("Namespace cannot be null or whitespace.", nameof(@namespace));
102→    if(string.IsNullOrWhiteSpace(key))
103→      throw new ArgumentException("Key cannot be null or whitespace.", nameof(key));
104→    if(data is null)
105→      throw new ArgumentNullException(nameof(data));
106→
107→    var storageKey = StorageKey.Generic(@namespace, key);
108→    await _adapter.Save(storageKey, data);
109→  }
110→
111→  /// <summary>
112→  /// Removes data from a generic namespace/key pair.
113→  /// </summary>
114→  /// <param name="namespace">The namespace for organizing keys.</param>
115→  /// <param name="key">The key within the namespace.</param>
116→  /// <exception cref="ArgumentException">Thrown if namespace or key is null or whitespace.</exception>
117→  public async Task Remove(string @namespace, string key)
118→  {
119→    ThrowIfDisposed();
120→
121→    if(string.IsNullOrWhiteSpace(@namespace))
122→      throw new ArgumentException("Namespace cannot be null or whitespace.", nameof(@namespace));
123→    if(string.IsNullOrWhiteSpace(key))
124→      throw new ArgumentException("Key cannot be null or whitespace.", nameof(key));
125→
126→    var storageKey = StorageKey.Generic(@namespace, key);
127→    await _adapter.Remove(storageKey);
128→  }
129→
130→  /// <summary>
131→  /// Loads a document from storage.
132→  /// </summary>
133→  /// <param name="documentId">The document identifier.</param>
134→  /// <returns>The loaded document, or null if not found in storage.</returns>
135→  /// <exception cref="ArgumentException">Thrown if documentId is null or whitespace.</exception>
136→  /// <exception cref="InvalidOperationException">Thrown if document data is corrupted.</exception>
137→  public async Task<AutomergeDocument?> LoadDoc(string documentId)
138→  {
139→    ThrowIfDisposed();
140→
141→    if(string.IsNullOrWhiteSpace(documentId))
142→      throw new ArgumentException("Document ID cannot be null or whitespace.", nameof(documentId));
143→
144→    // Create key prefix for all chunks of this document
145→    var prefix = new StorageKey(new[] { documentId });
146→
147→    // Load all chunks for this document
148→    var chunks = await _adapter.LoadRange(prefix);
149→
150→    if(chunks.Count == 0)
151→      return null;
152→
153→    // Separate snapshots and incrementals
154→    var snapshots = chunks.Where(c => c.Type == ChunkType.Snapshot).ToList();
155→    var incrementals = chunks.Where(c => c.Type == ChunkType.Incremental).ToList();
156→
157→    if(snapshots.Count == 0)
158→      throw new InvalidOperationException($"Document '{documentId}' has no snapshot in storage.");
159→
160→    // Load from the snapshot (should be only one after compaction, but take the first if multiple)
161→    var snapshot = snapshots[0];
162→    AutomergeDocument doc;
163→
164→    try
165→    {
166→      doc = AutomergeDocument.Load(snapshot.Data);
167→    }
168→    catch(Exception ex)
169→    {
170→      throw new InvalidOperationException($"Failed to load document '{documentId}' from snapshot.", ex);
171→    }
172→
173→    // Apply incremental changes in order
174→    foreach(var incremental in incrementals)
175→    {
176→      try
177→      {
178→        doc.LoadIncremental(incremental.Data);
179→      }
180→      catch(Exception ex)
181→      {
182→        doc.Dispose();
183→        throw new InvalidOperationException($"Failed to load incremental data for document '{documentId}'.", ex);
184→      }
185→    }
186→
187→    // Update tracked heads
188→    _lastSavedHeads[documentId] = doc.GetHeads();
189→
190→    // Emit event
191→    DocumentLoaded?.Invoke(this, new DocumentLoadedEventArgs(DocumentId.Parse(documentId)));
192→
193→    return doc;
194→  }
195→
196→  /// <summary>
197→  /// Saves a document to storage with automatic compaction.
198→  /// </summary>
199→  /// <param name="documentId">The document identifier.</param>
200→  /// <param name="doc">The document to save.</param>
201→  /// <exception cref="ArgumentException">Thrown if documentId is null or whitespace.</exception>
202→  /// <exception cref="ArgumentNullException">Thrown if doc is null.</exception>
203→  public async Task SaveDoc(string documentId, AutomergeDocument doc)
204→  {
205→    ThrowIfDisposed();
206→
207→    if(string.IsNullOrWhiteSpace(documentId))
208→      throw new ArgumentException("Document ID cannot be null or whitespace.", nameof(documentId));
209→    if(doc is null)
210→      throw new ArgumentNullException(nameof(doc));
211→
212→    await _saveLock.WaitAsync();
213→    try
214→    {
215→      var currentHeads = doc.GetHeads();
216→      if(currentHeads.Count == 0)
217→      {
218→        // No changes to save
219→        return;
220→      }
221→
222→      // Check if we should compact
223→      bool shouldCompact = await ShouldCompact(documentId);
224→      bool compacted = false;
225→
226→      if(shouldCompact)
227→      {
228→        // Compact: save new full snapshot and remove old chunks
229→        await CompactStorage(documentId, doc);
230→        compacted = true;
231→      }
232→      else
233→      {
234→        // Save incremental
235→        var lastHeads = _lastSavedHeads.TryGetValue(documentId, out var heads)
236→          ? heads
237→          : Array.Empty<string>();
238→
239→        byte[] incrementalData;
240→        try
241→        {
242→          incrementalData = doc.SaveAfter(lastHeads);
243→        }
244→        catch(Exception ex)
245→        {
246→          throw new InvalidOperationException($"Failed to save incremental data for document '{documentId}'.", ex);
247→        }
248→
249→        if(incrementalData.Length > 0)
250→        {
251→          // Generate key using current heads
252→          var headHash = currentHeads.Count > 0 ? currentHeads[0] : "empty";
253→          var incrementalKey = StorageKey.DocumentIncremental(documentId, headHash);
254→          await _adapter.Save(incrementalKey, incrementalData);
255→        }
256→      }
257→
258→      // Update last saved heads
259→      _lastSavedHeads[documentId] = currentHeads;
260→
261→      // Emit event
262→      DocumentSaved?.Invoke(this, new DocumentSavedEventArgs(DocumentId.Parse(documentId), compacted));
263→    }
264→    finally
265→    {
266→      _saveLock.Release();
267→    }
268→  }
269→
270→  /// <summary>
271→  /// Removes all storage for a document (snapshots, incrementals, sync states).
272→  /// </summary>
273→  /// <param name="documentId">The document identifier.</param>
274→  /// <exception cref="ArgumentException">Thrown if documentId is null or whitespace.</exception>
275→  public async Task RemoveDoc(string documentId)
276→  {
277→    ThrowIfDisposed();
278→
279→    if(string.IsNullOrWhiteSpace(documentId))
280→      throw new ArgumentException("Document ID cannot be null or whitespace.", nameof(documentId));
281→
282→    var prefix = new StorageKey(new[] { documentId });
283→    await _adapter.RemoveRange(prefix);
284→
285→    // Clear cached state
286→    _lastSavedHeads.Remove(documentId);
287→  }
288→
289→  /// <summary>
290→  /// Loads persisted sync state for a document and peer.
291→  /// </summary>
292→  /// <param name="documentId">The document identifier.</param>
293→  /// <param name="storageId">The storage or peer identifier.</param>
294→  /// <returns>The sync state if found; null otherwise.</returns>
295→  /// <exception cref="ArgumentException">Thrown if documentId is null or whitespace.</exception>
296→  public async Task<AutomergeSyncState?> LoadSyncState(string documentId, StorageId storageId)
297→  {
298→    ThrowIfDisposed();
299→
300→    if(string.IsNullOrWhiteSpace(documentId))
301→      throw new ArgumentException("Document ID cannot be null or whitespace.", nameof(documentId));
302→
303→    var key = StorageKey.DocumentSyncState(documentId, storageId);
304→    var data = await _adapter.Load(key);
305→
306→    if(data is null)
307→      return null;
308→
309→    try
310→    {
311→      return AutomergeSyncState.Decode(data);
312→    }
313→    catch(Exception ex)
314→    {
315→      throw new InvalidOperationException(
316→        $"Failed to decode sync state for document '{documentId}' and storage '{storageId}'.", ex);
317→    }
318→  }
319→
320→  /// <summary>
321→  /// Persists sync state for a document and peer.
322→  /// </summary>
323→  /// <param name="documentId">The document identifier.</param>
324→  /// <param name="storageId">The storage or peer identifier.</param>
325→  /// <param name="syncState">The sync state to persist.</param>
326→  /// <exception cref="ArgumentException">Thrown if documentId is null or whitespace.</exception>
327→  /// <exception cref="ArgumentNullException">Thrown if syncState is null.</exception>
328→  public async Task SaveSyncState(string documentId, StorageId storageId, AutomergeSyncState syncState)
329→  {
330→    ThrowIfDisposed();
331→
332→    if(string.IsNullOrWhiteSpace(documentId))
333→      throw new ArgumentException("Document ID cannot be null or whitespace.", nameof(documentId));
334→    if(syncState is null)
335→      throw new ArgumentNullException(nameof(syncState));
336→
337→    var key = StorageKey.DocumentSyncState(documentId, storageId);
338→    var data = syncState.Encode();
339→    await _adapter.Save(key, data);
340→  }
341→
