  3→using System.Timers;
  4→using Ray.Automerge;
  5→using Timer = System.Timers.Timer;
  6→
  7→namespace DemoApp.CollaborativeEditor.Services;
  8→
  9→/// <summary>
 10→/// Manages sync state between the local document and a simulated peer document.
 11→/// Uses the Automerge sync protocol (GenerateSyncMessage / ReceiveSyncMessage)
 12→/// on a periodic timer to demonstrate real-time collaborative synchronization
 13→/// of rich text with formatting marks and block structure.
 14→/// </summary>
 15→sealed class SyncService : IDisposable
 16→{
 17→  readonly AutomergeService _local;
 18→  readonly AutomergeService _peer;
 19→  readonly AutomergeSyncState _syncLocalToPeer;
 20→  readonly AutomergeSyncState _syncPeerToLocal;
 21→  readonly Timer _syncTimer;
 22→  readonly object _syncLock = new();
 23→  bool _disposed;
 24→
 25→  /// <summary>
 26→  /// Fired after a sync round completes, on the timer thread.
 27→  /// </summary>
 28→  public event Action? SyncCompleted;
 29→
 30→  /// <summary>
 31→  /// Fired when the peer makes a simulated edit, on the timer thread.
 32→  /// </summary>
 33→  public event Action? PeerEdited;
 34→
 35→  public SyncService(AutomergeService local, AutomergeService peer)
 36→  {
 37→    _local = local;
 38→    _peer = peer;
 39→
 40→    _syncLocalToPeer = _local.Document.CreateSyncState();
 41→    _syncPeerToLocal = _peer.Document.CreateSyncState();
 42→
 43→    _syncTimer = new Timer(500);
 44→    _syncTimer.Elapsed += OnSyncTimerElapsed;
 45→    _syncTimer.AutoReset = true;
 46→  }
 47→
 48→  /// <summary>
 49→  /// Gets the number of connected peers (always 1 in this demo).
 50→  /// </summary>
 51→  public int PeerCount => 1;
 52→
 53→  /// <summary>
 54→  /// Gets whether the sync service is actively running.
 55→  /// </summary>
 56→  public bool IsRunning => _syncTimer.Enabled;
 57→
 58→  /// <summary>
 59→  /// Gets the text content of the simulated peer document.
 60→  /// </summary>
 61→  public string GetPeerText()
 62→  {
 63→    lock(_syncLock)
 64→    {
 65→      return _peer.GetText();
 66→    }
 67→  }
 68→
 69→  /// <summary>
 70→  /// Starts periodic synchronization between local and peer documents.
 71→  /// </summary>
 72→  public void Start()
 73→  {
 74→    ThrowIfDisposed();
 75→    RunSyncRound();
 76→    _syncTimer.Start();
 77→  }
 78→
 79→  /// <summary>
 80→  /// Stops periodic synchronization.
 81→  /// </summary>
 82→  public void Stop()
 83→  {
 84→    _syncTimer.Stop();
 85→  }
 86→
 87→  /// <summary>
 88→  /// Simulates a remote peer editing the document concurrently.
 89→  /// </summary>
 90→  public void SimulatePeerEdit(string text, ulong index)
 91→  {
 92→    ThrowIfDisposed();
 93→    lock(_syncLock)
 94→    {
 95→      _peer.SpliceText(index, 0, text);
 96→    }
 97→
 98→    PeerEdited?.Invoke();
 99→  }
100→
101→  /// <summary>
102→  /// Runs one round of bidirectional sync (local to peer, peer to local).
103→  /// Returns true if any messages were exchanged.
104→  /// </summary>
105→  public bool RunSyncRound()
106→  {
107→    lock(_syncLock)
108→    {
109→      bool exchanged = false;
110→
111→      for(int i = 0; i < 10; i++)
112→      {
113→        byte[]? msgLocalToPeer = _local.Document.GenerateSyncMessage(_syncLocalToPeer);
114→        byte[]? msgPeerToLocal = _peer.Document.GenerateSyncMessage(_syncPeerToLocal);
115→
116→        if(msgLocalToPeer is null && msgPeerToLocal is null)
117→        {
118→          break;
119→        }
120→
121→        if(msgLocalToPeer is not null)
122→        {
123→          _peer.Document.ReceiveSyncMessage(_syncPeerToLocal, msgLocalToPeer);
124→          exchanged = true;
125→        }
126→
127→        if(msgPeerToLocal is not null)
128→        {
129→          _local.Document.ReceiveSyncMessage(_syncLocalToPeer, msgPeerToLocal);
130→          exchanged = true;
131→        }
132→      }
133→
134→      return exchanged;
135→    }
136→  }
137→
138→  void OnSyncTimerElapsed(object? sender, ElapsedEventArgs e)
139→  {
140→    if(_disposed)
141→    {
142→      return;
143→    }
144→
145→    bool exchanged = RunSyncRound();
146→    if(exchanged)
147→    {
148→      SyncCompleted?.Invoke();
149→    }
150→  }
151→
152→  public void Dispose()
153→  {
154→    if(!_disposed)
155→    {
156→      _disposed = true;
157→      _syncTimer.Stop();
158→      _syncTimer.Dispose();
159→      _syncLocalToPeer.Dispose();
160→      _syncPeerToLocal.Dispose();
161→      _peer.Dispose();
162→    }
163→  }
164→
165→  void ThrowIfDisposed()
166→  {
167→    ObjectDisposedException.ThrowIf(_disposed, this);
168→  }
169→}
