  5→/// <summary>
  6→/// Represents a Base58Check-encoded Automerge document identifier.
  7→/// Mirrors the branded string type from the TypeScript implementation.
  8→/// </summary>
  9→[PublicAPI]
 10→[ExcludeFromCodeCoverage]
 11→public readonly record struct DocumentId
 12→{
 13→  /// <summary>
 14→  /// Gets the encoded document identifier value.
 15→  /// </summary>
 16→  public string Value { get; }
 17→
 18→  /// <summary>
 19→  /// Initializes a new instance of the <see cref="DocumentId"/> struct.
 20→  /// </summary>
 21→  /// <param name="value">Base58Check-encoded document identifier.</param>
 22→  /// <exception cref="ArgumentException">Thrown when the value is null or whitespace.</exception>
 23→  public DocumentId(string value)
 24→  {
 25→    if(string.IsNullOrWhiteSpace(value))
 26→      throw new ArgumentException("Document ID cannot be null or whitespace.", nameof(value));
 27→
 28→    Value = value;
 29→  }
 30→
 31→  /// <summary>
 32→  /// Generates a new random document identifier.
 33→  /// </summary>
 34→  /// <returns>A new <see cref="DocumentId"/> value.</returns>
 35→  public static DocumentId Generate()
 36→  {
 37→    var uuid = Guid.NewGuid().ToByteArray();
 38→    return FromBinary(uuid);
 39→  }
 40→
 41→  /// <summary>
 42→  /// Creates a <see cref="DocumentId"/> from its binary representation.
 43→  /// </summary>
 44→  /// <param name="bytes">Binary data to encode.</param>
 45→  /// <returns>The encoded document identifier.</returns>
 46→  /// <exception cref="ArgumentNullException">Thrown when bytes is null.</exception>
 47→  /// <exception cref="ArgumentException">Thrown when bytes is empty.</exception>
 48→  public static DocumentId FromBinary(byte[] bytes)
 49→  {
 50→    if(bytes is null)
 51→      throw new ArgumentNullException(nameof(bytes));
 52→
 53→    if(bytes.Length == 0)
 54→      throw new ArgumentException("Document ID binary representation cannot be empty.", nameof(bytes));
 55→
 56→    if(bytes.Length < 16)
 57→      throw new ArgumentException("Document ID binary representation must be at least 16 bytes.", nameof(bytes));
 58→
 59→    var encoded = Base58Check.Encode(bytes);
 60→    return new DocumentId(encoded);
 61→  }
 62→
 63→  /// <summary>
 64→  /// Creates a <see cref="DocumentId"/> from its binary representation.
 65→  /// </summary>
 66→  /// <param name="bytes">Binary data to encode.</param>
 67→  /// <returns>The encoded document identifier.</returns>
 68→  /// <exception cref="ArgumentException">Thrown when bytes is empty.</exception>
 69→  public static DocumentId FromBinary(ReadOnlySpan<byte> bytes)
 70→  {
 71→    if(bytes.Length == 0)
 72→      throw new ArgumentException("Document ID binary representation cannot be empty.", nameof(bytes));
 73→
 74→    if(bytes.Length < 16)
 75→      throw new ArgumentException("Document ID binary representation must be at least 16 bytes.", nameof(bytes));
 76→
 77→    var buffer = bytes.ToArray();
 78→    return FromBinary(buffer);
 79→  }
 80→
 81→  /// <summary>
 82→  /// Converts a document identifier to its binary representation.
 83→  /// </summary>
 84→  /// <param name="documentId">Document identifier to convert.</param>
 85→  /// <returns>The binary representation.</returns>
 86→  public static byte[] ToBinary(DocumentId documentId)
 87→  {
 88→    return documentId.ToBinary();
 89→  }
 90→
 91→  /// <summary>
 92→  /// Converts a document identifier string to its binary representation.
 93→  /// </summary>
 94→  /// <param name="value">Document identifier value.</param>
 95→  /// <returns>The binary representation.</returns>
 96→  public static byte[] ToBinary(string value)
 97→  {
 98→    return Parse(value).ToBinary();
 99→  }
100→
101→  /// <summary>
102→  /// Parses a string into a <see cref="DocumentId"/>.
103→  /// </summary>
104→  /// <param name="value">The encoded document identifier.</param>
105→  /// <returns>The parsed <see cref="DocumentId"/>.</returns>
106→  /// <exception cref="ArgumentException">Thrown when value is null or whitespace.</exception>
107→  /// <exception cref="FormatException">Thrown when value is not a valid document identifier.</exception>
108→  public static DocumentId Parse(string value)
109→  {
110→    if(string.IsNullOrWhiteSpace(value))
111→      throw new ArgumentException("Document ID cannot be null or whitespace.", nameof(value));
112→
113→    if(!TryParse(value, out var documentId))
114→      throw new FormatException($"Invalid document ID: {value}");
115→
116→    return documentId;
117→  }
118→
119→  /// <summary>
120→  /// Attempts to parse a string into a <see cref="DocumentId"/>.
121→  /// </summary>
122→  /// <param name="value">Value to parse.</param>
123→  /// <param name="documentId">Resulting document identifier.</param>
124→  /// <returns>True when the value is a valid document identifier.</returns>
125→  public static bool TryParse(string? value, out DocumentId documentId)
126→  {
127→    if(string.IsNullOrWhiteSpace(value))
128→    {
129→      documentId = default;
130→      return false;
131→    }
132→
133→    try
134→    {
135→      var binary = Base58Check.Decode(value);
136→      if(binary.Length < 16)
137→      {
138→        documentId = default;
139→        return false;
140→      }
141→
142→      documentId = new DocumentId(value);
143→      return true;
144→    }
145→    catch
146→    {
147→      documentId = default;
148→      return false;
149→    }
150→  }
151→
152→  /// <summary>
153→  /// Determines if the provided value is a valid document identifier.
154→  /// </summary>
155→  /// <param name="value">Value to validate.</param>
156→  /// <returns>True when the value is valid.</returns>
157→  public static bool IsValid(string? value)
158→  {
159→    return TryParse(value, out _);
160→  }
161→
162→  /// <summary>
163→  /// Converts the document identifier to its binary representation.
164→  /// </summary>
165→  /// <returns>Binary representation of the identifier.</returns>
166→  public byte[] ToBinary()
167→  {
168→    return Base58Check.Decode(Value);
169→  }
170→
171→  /// <inheritdoc />
172→  public override string ToString()
173→  {
174→    return Value;
175→  }
176→
177→  /// <summary>
178→  /// Implicit conversion to string for interop with existing APIs.
179→  /// </summary>
180→  /// <param name="documentId">Document identifier.</param>
181→  public static implicit operator string(DocumentId documentId)
182→  {
183→    return documentId.Value;
184→  }
185→
186→  /// <summary>
187→  /// Implicit conversion from string to <see cref="DocumentId"/>.
188→  /// </summary>
189→  /// <param name="value">Document identifier value.</param>
190→  /// <exception cref="FormatException">Thrown when value is not a valid identifier.</exception>
191→  public static implicit operator DocumentId(string value)
192→  {
193→    return Parse(value);
194→  }
195→}
