 3→/// <summary>
 4→/// Uniquely identifies a peer in the network.
 5→/// </summary>
 6→[PublicAPI]
 7→public readonly record struct PeerId
 8→{
 9→  readonly string _value;
10→
11→  public PeerId(string value)
12→  {
13→    if(string.IsNullOrWhiteSpace(value))
14→      throw new ArgumentException("PeerId cannot be null or whitespace", nameof(value));
15→    _value = value;
16→  }
17→
18→  /// <summary>
19→  /// Generates a new unique PeerId with format "peer-{random}".
20→  /// Mirrors the TypeScript implementation which uses Math.random().toString(36).slice(4).
21→  /// </summary>
22→  public static PeerId Generate()
23→  {
24→    var guid = Guid.NewGuid();
25→    var randomStr = guid.ToString("N").Substring(0, 8);
26→    return new($"peer-{randomStr}");
27→  }
28→
29→  public static implicit operator string(PeerId id) => id._value;
30→  public static implicit operator PeerId(string value) => new(value);
31→
32→  public override string ToString() => _value;
33→}

