  3→/// <summary>
  4→/// In-memory network adapter for testing. Messages are delivered synchronously.
  5→/// </summary>
  6→/// <remarks>
  7→/// This adapter is useful for unit and integration tests where you need to simulate
  8→/// network communication without actual network infrastructure.
  9→/// Messages are delivered immediately and synchronously to all connected peers.
 10→/// </remarks>
 11→[PublicAPI]
 12→public sealed class InMemoryNetworkAdapter : INetworkAdapter
 13→{
 14→  readonly List<InMemoryNetworkAdapter> _connectedAdapters = [];
 15→  readonly PeerId _localPeerId;
 16→  readonly object _lock = new();
 17→  
 18→  public string AdapterId { get; }
 19→  public bool IsReady => true;
 20→  public Task WhenReady() => Task.CompletedTask;
 21→
 22→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 23→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 24→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 25→  public event EventHandler? Closed;
 26→  
 27→  
 28→
 29→  /// <summary>
 30→  /// Initializes a new instance of the InMemoryNetworkAdapter.
 31→  /// </summary>
 32→  /// <param name="localPeerId">The peer ID for this adapter. If null, a new ID will be generated.</param>
 33→  public InMemoryNetworkAdapter(PeerId? localPeerId = null)
 34→  {
 35→    _localPeerId = localPeerId ?? PeerId.Generate();
 36→    AdapterId = $"in-memory-{_localPeerId}";
 37→  }
 38→
 39→
 40→  /// <summary>
 41→  /// Connects this adapter to another in-memory adapter.
 42→  /// This establishes a bidirectional connection between the two adapters.
 43→  /// </summary>
 44→  /// <param name="otherAdapter">The adapter to connect to.</param>
 45→  public void ConnectTo(InMemoryNetworkAdapter otherAdapter)
 46→  {
 47→    if(otherAdapter is null) throw new ArgumentNullException(nameof(otherAdapter));
 48→    if(otherAdapter == this) throw new ArgumentException("Cannot connect to self", nameof(otherAdapter));
 49→
 50→    lock(_lock)
 51→    {
 52→      if(_connectedAdapters.Contains(otherAdapter)) return;
 53→
 54→      _connectedAdapters.Add(otherAdapter);
 55→    }
 56→
 57→    lock(otherAdapter._lock)
 58→    {
 59→      if(!otherAdapter._connectedAdapters.Contains(this))
 60→      {
 61→        otherAdapter._connectedAdapters.Add(this);
 62→      }
 63→    }
 64→
 65→    // Notify peer candidate events
 66→    PeerCandidate?.Invoke(this, new PeerCandidateEventArgs { PeerId = otherAdapter._localPeerId, Metadata = null });
 67→
 68→    otherAdapter.PeerCandidate?.Invoke(otherAdapter,
 69→      new PeerCandidateEventArgs { PeerId = _localPeerId, Metadata = null });
 70→  }
 71→
 72→  /// <inheritdoc />
 73→  public void Connect(PeerId peerId, PeerMetadata? metadata = null)
 74→  {
 75→    // No-op for in-memory adapter (use ConnectTo instead)
 76→  }
 77→
 78→  /// <inheritdoc />
 79→  public void Send(IRepoMessage message)
 80→  {
 81→    if(message is null) throw new ArgumentNullException(nameof(message));
 82→
 83→    // Add sender ID
 84→    var messageWithSender = message.WithSender(_localPeerId);
 85→
 86→    // Deliver to all connected adapters
 87→    List<InMemoryNetworkAdapter> adapters;
 88→    lock(_lock)
 89→    {
 90→      adapters = _connectedAdapters.ToList();
 91→    }
 92→
 93→    foreach(var adapter in adapters)
 94→    {
 95→      adapter.MessageReceived?.Invoke(adapter, new MessageReceivedEventArgs { Message = messageWithSender });
 96→    }
 97→  }
 98→
 99→  /// <inheritdoc />
100→  public Task Disconnect()
101→  {
102→    List<InMemoryNetworkAdapter> adapters;
103→    lock(_lock)
104→    {
105→      adapters = _connectedAdapters.ToList();
106→      _connectedAdapters.Clear();
107→    }
108→
109→    foreach(var adapter in adapters)
110→    {
111→      lock(adapter._lock)
112→      {
113→        adapter._connectedAdapters.Remove(this);
114→      }
115→
116→      adapter.PeerDisconnected?.Invoke(adapter, new PeerDisconnectedEventArgs { PeerId = _localPeerId });
117→    }
118→
119→    Closed?.Invoke(this, EventArgs.Empty);
120→
121→    return Task.CompletedTask;
122→  }
123→}

