  3→/// <summary>
  4→/// SignalR hub for Automerge document synchronization.
  5→/// </summary>
  6→/// <remarks>
  7→/// This hub provides real-time message routing between connected peers for document collaboration.
  8→/// Messages are organized into document-specific groups, ensuring efficient targeted delivery.
  9→///
 10→/// <para>
 11→/// <strong>Key Features:</strong>
 12→/// <list type="bullet">
 13→///   <item><description>Document-based group management (one group per document ID)</description></item>
 14→///   <item><description>Automatic subscription on first message send</description></item>
 15→///   <item><description>Echo prevention (senders don't receive their own messages)</description></item>
 16→///   <item><description>Graceful error handling with comprehensive logging</description></item>
 17→/// </list>
 18→/// </para>
 19→///
 20→/// <para>
 21→/// <strong>Usage Example (ASP.NET Core):</strong>
 22→/// <code>
 23→/// app.MapHub&lt;DocumentsHub&gt;("/hubs/documents");
 24→/// </code>
 25→/// </para>
 26→/// </remarks>
 27→[PublicAPI]
 28→public class DocumentsHub : Hub<IDocumentsHubClient>, IDocumentsHub
 29→{
 30→  readonly ILogger<DocumentsHub> _logger;
 31→
 32→  /// <summary>
 33→  /// Initializes a new instance of the <see cref="DocumentsHub"/> class.
 34→  /// </summary>
 35→  /// <param name="logger">The logger instance.</param>
 36→  public DocumentsHub(ILogger<DocumentsHub> logger)
 37→  {
 38→    _logger = logger ?? throw new ArgumentNullException(nameof(logger));
 39→  }
 40→
 41→  /// <inheritdoc />
 42→  public async Task Handshake(PeerHandshakeDto handshake)
 43→  {
 44→    try
 45→    {
 46→      _logger.LogInformation(
 47→        "Peer handshake: PeerId={PeerId}, ConnectionId={ConnectionId}, IsEphemeral={IsEphemeral}",
 48→        handshake.PeerId,
 49→        Context.ConnectionId,
 50→        handshake.Metadata?.IsEphemeral ?? false);
 51→
 52→      // Store peer ID in connection context for later use
 53→      Context.Items["PeerId"] = handshake.PeerId;
 54→
 55→      // Broadcast peer join to all OTHER clients (not the joining client itself)
 56→      // This enables peer discovery for document synchronization
 57→      await Clients.Others.OnPeerJoined(handshake);
 58→
 59→      _logger.LogDebug(
 60→        "Peer join broadcasted to all other clients: PeerId={PeerId}",
 61→        handshake.PeerId);
 62→    }
 63→    catch (Exception ex)
 64→    {
 65→      _logger.LogError(ex, "Error during handshake for ConnectionId={ConnectionId}", Context.ConnectionId);
 66→    }
 67→  }
 68→
 69→  /// <inheritdoc />
 70→  public async Task SubscribeToDocument(string documentId)
 71→  {
 72→    try
 73→    {
 74→      if (string.IsNullOrEmpty(documentId))
 75→      {
 76→        _logger.LogWarning("Attempt to subscribe with null/empty documentId. ConnectionId={ConnectionId}",
 77→          Context.ConnectionId);
 78→        return;
 79→      }
 80→
 81→      await Groups.AddToGroupAsync(Context.ConnectionId, documentId);
 82→
 83→      _logger.LogInformation(
 84→        "Peer subscribed to document: DocumentId={DocumentId}, ConnectionId={ConnectionId}, PeerId={PeerId}",
 85→        documentId,
 86→        Context.ConnectionId,
 87→        Context.Items.TryGetValue("PeerId", out var peerId) ? peerId : "unknown");
 88→    }
 89→    catch (Exception ex)
 90→    {
 91→      _logger.LogError(ex, "Error subscribing to document {DocumentId} for ConnectionId={ConnectionId}",
 92→        documentId, Context.ConnectionId);
 93→    }
 94→  }
 95→
 96→  /// <inheritdoc />
 97→  public async Task UnsubscribeFromDocument(string documentId)
 98→  {
 99→    try
100→    {
101→      if (string.IsNullOrEmpty(documentId))
102→      {
103→        _logger.LogWarning("Attempt to unsubscribe with null/empty documentId. ConnectionId={ConnectionId}",
104→          Context.ConnectionId);
105→        return;
106→      }
107→
108→      await Groups.RemoveFromGroupAsync(Context.ConnectionId, documentId);
109→
110→      _logger.LogInformation(
111→        "Peer unsubscribed from document: DocumentId={DocumentId}, ConnectionId={ConnectionId}, PeerId={PeerId}",
112→        documentId,
113→        Context.ConnectionId,
114→        Context.Items.TryGetValue("PeerId", out var peerId) ? peerId : "unknown");
115→    }
116→    catch (Exception ex)
117→    {
118→      _logger.LogError(ex, "Error unsubscribing from document {DocumentId} for ConnectionId={ConnectionId}",
119→        documentId, Context.ConnectionId);
120→    }
121→  }
122→
123→  /// <inheritdoc />
124→  public async Task SendMessage(MessageDto message)
125→  {
126→    try
127→    {
128→      if (string.IsNullOrEmpty(message.DocumentId))
129→      {
130→        _logger.LogWarning(
131→          "Received message with null/empty DocumentId. MessageType={MessageType}, SenderId={SenderId}, ConnectionId={ConnectionId}",
132→          message.MessageType,
133→          message.SenderId,
134→          Context.ConnectionId);
135→        return;
136→      }
137→
138→      _logger.LogInformation(
139→        "Received message from client. DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}, ConnectionId={ConnectionId}",
140→        message.DocumentId,
141→        message.MessageType,
142→        message.SenderId,
143→        Context.ConnectionId);
144→
145→      _logger.LogDebug(
146→        "Routing message: DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}, ConnectionId={ConnectionId}, DataSize={DataSize}",
147→        message.DocumentId,
148→        message.MessageType,
149→        message.SenderId,
150→        Context.ConnectionId,
151→        message.Data?.Length ?? 0);
152→
153→      // Auto-subscribe sender to document group if not already subscribed
154→      // This ensures messages are delivered even if explicit subscription wasn't called
155→      await Groups.AddToGroupAsync(Context.ConnectionId, message.DocumentId);
156→
157→      // Broadcast to all group members EXCEPT the sender (prevents echo-back)
158→      await Clients.OthersInGroup(message.DocumentId).OnReceiveMessage(message);
159→
160→      _logger.LogDebug(
161→        "Message routed successfully: DocumentId={DocumentId}, MessageType={MessageType}",
162→        message.DocumentId,
163→        message.MessageType);
164→    }
165→    catch (Exception ex)
166→    {
167→      _logger.LogError(ex,
168→        "Error routing message: DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}, ConnectionId={ConnectionId}",
169→        message.DocumentId,
170→        message.MessageType,
171→        message.SenderId,
172→        Context.ConnectionId);
173→    }
174→  }
175→
176→  /// <summary>
177→  /// Called when a new connection is established.
178→  /// </summary>
179→  public override Task OnConnectedAsync()
180→  {
181→    _logger.LogInformation("Client connected: ConnectionId={ConnectionId}", Context.ConnectionId);
182→    return base.OnConnectedAsync();
183→  }
184→
185→  /// <summary>
186→  /// Called when a connection is terminated.
187→  /// </summary>
188→  /// <param name="exception">The exception that caused the disconnect, if any.</param>
189→  public override async Task OnDisconnectedAsync(Exception? exception)
190→  {
191→    var peerId = Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
192→
193→    if (exception is not null)
194→    {
195→      _logger.LogWarning(exception,
196→        "Client disconnected with error: ConnectionId={ConnectionId}, PeerId={PeerId}",
197→        Context.ConnectionId,
198→        peerId ?? "unknown");
199→    }
200→    else
201→    {
202→      _logger.LogInformation(
203→        "Client disconnected: ConnectionId={ConnectionId}, PeerId={PeerId}",
204→        Context.ConnectionId,
205→        peerId ?? "unknown");
206→    }
207→
208→    // Broadcast peer left to all other clients if we have a peer ID
209→    if (!string.IsNullOrEmpty(peerId))
210→    {
211→      await Clients.Others.OnPeerLeft(peerId);
212→
213→      _logger.LogDebug(
214→        "Peer left broadcasted to all other clients: PeerId={PeerId}",
215→        peerId);
216→    }
217→
218→    await base.OnDisconnectedAsync(exception);
219→  }
220→}
