 168→  
 169→  /// <summary>
 170→  /// Disposes the repository and releases all resources.
 171→  /// </summary>
 172→  public void Dispose()
 173→  {
 174→    if(_isDisposed) return;
 175→
 176→    _isDisposed = true;
 177→
 178→    // Cancel all pending saves
 179→    _saveLock.Wait();
 180→    try
 181→    {
 182→      foreach(var cts in _pendingSaves.Values)
 183→      {
 184→        cts.Cancel();
 185→        cts.Dispose();
 186→      }
 187→
 188→      _pendingSaves.Clear();
 189→    }
 190→    finally
 191→    {
 192→      _saveLock.Release();
 193→    }
 194→
 195→    // Dispose synchronizer
 196→    _synchronizer.Dispose();
 197→
 198→    // Dispose network subsystem
 199→    _network.Dispose();
 200→
 201→    // Dispose storage subsystem
 202→    _storage?.Dispose();
 203→
 204→    // Dispose all handles
 205→
 206→    _handleLock.Wait();
 207→    try
 208→    {
 209→      foreach(var handle in _handleCache.Values)
 210→      {
 211→        handle.Dispose();
 212→      }
 213→
 214→      _handleCache.Clear();
 215→    }
 216→    finally
 217→    {
 218→      _handleLock.Release();
 219→    }
 220→
 221→    // Dispose locks
 222→    _handleLock.Dispose();
 223→    _saveLock.Dispose();
 224→  }
