 596→  #region Document Lifecycle - Delete, Clone, Import, Export
 597→
 598→  /// <summary>
 599→  /// Deletes a document from the repository.
 600→  /// Mirrors the synchronous TypeScript Repo.delete() API.
 601→  /// </summary>
 602→  /// <param name="documentId">The document ID to delete.</param>
 603→  public void Delete(string documentId)
 604→  {
 605→    if(string.IsNullOrWhiteSpace(documentId))
 606→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 607→
 608→    ThrowIfDisposed();
 609→
 610→    _handleLock.Wait();
 611→    IDocHandle? handle;
 612→    try
 613→    {
 614→      if(!_handleCache.TryGetValue(documentId, out handle))
 615→      {
 616→        return;
 617→      }
 618→
 619→      _handleCache.Remove(documentId);
 620→    }
 621→    finally
 622→    {
 623→      _handleLock.Release();
 624→    }
 625→
 626→    // Unregister from subsystems (synchronous)
 627→    _synchronizer.RemoveDocument(documentId);
 628→
 629→    // Mark handle as deleted
 630→    handle.Delete();
 631→
 632→    // Emit event
 633→    DocumentDeleted?.Invoke(this, new DocumentDeletedEventArgs { DocumentId = handle.DocumentId });
 634→
 635→    // Fire-and-forget storage deletion to maintain sync API
 636→    if(_storage is not null)
 637→    {
 638→      _ = Task.Run(async () =>
 639→      {
 640→        try
 641→        {
 642→          await _storage.RemoveDoc(documentId);
 643→        }
 644→        catch(Exception ex)
 645→        {
 646→          // Log but don't throw - storage deletion shouldn't block document deletion
 647→          // In production, use proper logging
 648→          System.Diagnostics.Debug.WriteLine($"Failed to delete document from storage: {ex}");
 649→        }
 650→      });
 651→    }
 652→  }
 653→
 654→  /// <summary>
 655→  /// Creates a new document as a clone of an existing document.
 656→  /// </summary>
 657→  /// <typeparam name="T">The document content type.</typeparam>
 658→  /// <param name="source">The source handle to clone.</param>
 659→  /// <returns>A handle to the cloned document.</returns>
 660→  public DocHandle<T> Clone<T>(DocHandle<T> source)
 661→  {
 662→    if(source is null)
 663→      throw new ArgumentNullException(nameof(source));
 664→
 665→    ThrowIfDisposed();
 666→
 667→    // Generate new document ID
 668→    var newDocumentId = _idFactory is not null
 669→      ? DocumentId.FromBinary(_idFactory(Array.Empty<string>()).GetAwaiter().GetResult())
 670→      : DocumentId.Generate();
 671→
 672→    // Clone the underlying document
 673→    var sourceDocHandle = source;
 674→    var sourceDoc = sourceDocHandle.Doc();
 675→    var clonedDocBytes = (sourceDoc as AutomergeDocument)!.Save();
 676→    var clonedDoc = AutomergeDocument.Load(clonedDocBytes);
 677→
 678→    // Create new handle
 679→    var handle = new DocHandle<T>(
 680→      newDocumentId,
 681→      new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 682→      clonedDoc);
 683→
 684→    _handleLock.Wait();
 685→    try
 686→    {
 687→      _handleCache[newDocumentId] = handle;
 688→    }
 689→    finally
 690→    {
 691→      _handleLock.Release();
 692→    }
 693→
 694→    // Register with subsystems
 695→    RegisterHandle(newDocumentId, handle);
 696→
 697→    // Emit event
 698→    DocumentLoaded?.Invoke(this,
 699→      new DocumentEventArgs { DocumentId = newDocumentId, Handle = handle });
 700→
 701→    return handle;
 702→  }
 703→
 704→  /// <summary>
 705→  /// Exports a document as binary data.
 706→  /// </summary>
 707→  /// <param name="documentId">The document ID to export.</param>
 708→  /// <returns>The binary representation of the document, or null if not found.</returns>
 709→  public async Task<byte[]?> Export(string documentId)
 710→  {
 711→    if(string.IsNullOrWhiteSpace(documentId))
 712→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 713→
 714→    ThrowIfDisposed();
 715→
 716→    // Try to get from cache first
 717→    await _handleLock.WaitAsync();
 718→    IDocHandle? handle;
 719→    try
 720→    {
 721→      if(!_handleCache.TryGetValue(documentId, out handle))
 722→      {
 723→        // Not in cache, try loading from storage
 724→        if(_storage is not null)
 725→        {
 726→          var doc = await _storage.LoadDoc(documentId);
 727→          if(doc is not null)
 728→          {
 729→            return doc.Save();
 730→          }
 731→        }
 732→
 733→        return null;
 734→      }
 735→    }
 736→    finally
 737→    {
 738→      _handleLock.Release();
 739→    }
 740→
 741→    // Export from handle
 742→    var document = handle.GetDocument();
 743→    return document!.Save();
 744→  }
