 746→  /// <summary>
 747→  /// Imports a document from binary data.
 748→  /// </summary>
 749→  /// <typeparam name="T">The document content type.</typeparam>
 750→  /// <param name="data">The binary data to import.</param>
 751→  /// <param name="documentId">Optional document ID. If null, a new ID is generated.</param>
 752→  /// <returns>A handle to the imported document.</returns>
 753→  public DocHandle<T> Import<T>(byte[] data, string? documentId = null)
 754→  {
 755→    if(data is null || data.Length == 0)
 756→      throw new ArgumentException("Data cannot be null or empty", nameof(data));
 757→
 758→    ThrowIfDisposed();
 759→
 760→    // Load document from binary
 761→    var doc = AutomergeDocument.Load(data);
 762→
 763→    // Generate or validate document ID
 764→    if(documentId is null)
 765→    {
 766→      // Extract ID from document heads
 767→      var heads = doc.GetHeads();
 768→      documentId = _idFactory is not null
 769→        ? DocumentId.FromBinary(_idFactory(heads).GetAwaiter().GetResult())
 770→        : DocumentId.Generate();
 771→    }
 772→    else if(!DocumentId.IsValid(documentId))
 773→    {
 774→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 775→    }
 776→
 777→    // Create handle
 778→    var handle = new DocHandle<T>(
 779→      documentId,
 780→      new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>() },
 781→      doc);
 782→
 783→    _handleLock.Wait();
 784→    try
 785→    {
 786→      // Check if already exists
 787→      if(_handleCache.ContainsKey(documentId))
 788→      {
 789→        throw new InvalidOperationException($"Document already exists: {documentId}");
 790→      }
 791→
 792→      _handleCache[documentId] = handle;
 793→    }
 794→    finally
 795→    {
 796→      _handleLock.Release();
 797→    }
 798→
 799→    // Register with subsystems
 800→    RegisterHandle(documentId, handle);
 801→
 802→    // Emit event
 803→    DocumentLoaded?.Invoke(this,
 804→      new DocumentEventArgs { DocumentId = DocumentId.Parse(documentId), Handle = handle });
 805→
 806→    return handle;
 807→  }
