 811→  #region Subsystem Wiring
 812→
 813→  /// <summary>
 814→  /// Registers a handle with all subsystems and wires up events.
 815→  /// </summary>
 816→  void RegisterHandle<T>(string documentId, DocHandle<T> handle)
 817→  {
 818→    // Wire up handle events
 819→    handle.HeadsChanged += (sender, args) => OnHandleHeadsChanged(documentId, args);
 820→    handle.Deleted += (sender, args) => OnHandleDeleted(documentId);
 821→    handle.EphemeralMessageOutbound += (sender, args) => OnHandleEphemeralMessage(documentId, args);
 822→
 823→    // Register with synchronizer
 824→    _synchronizer.AddDocument(documentId);
 825→  }
 826→
 827→  /// <summary>
 828→  /// Handles document changes, triggering throttled save.
 829→  /// </summary>
 830→  void OnHandleHeadsChanged<T>(string documentId, DocHandleHeadsChangedEventArgs<T> args)
 831→  {
 832→    // Trigger throttled save
 833→    ScheduleSave(documentId);
 834→
 835→    _synchronizer.NotifyDocumentChanged(documentId);
 836→  }
 837→
 838→  /// <summary>
 839→  /// Handles document deletion.
 840→  /// </summary>
 841→  void OnHandleDeleted(string documentId)
 842→  {
 843→    // Remove from cache
 844→    _handleLock.Wait();
 845→    try
