1036→  void UpdateDocument(string documentId, AutomergeDocument document)
1037→  {
1038→    _handleLock.Wait();
1039→    IDocHandle? handle;
1040→    try
1041→    {
1042→      if(!_handleCache.TryGetValue(documentId, out handle))
1043→      {
1044→        return;
1045→      }
1046→    }
1047→    finally
1048→    {
1049→      _handleLock.Release();
1050→    }
1051→
1052→    // If handle is not initialized (requesting from network), initialize it now
1053→    if(handle.State == HandleState.Requesting || handle.State == HandleState.Loading)
1054→    {
