  3→/// <summary>
  4→/// In-memory storage adapter for testing and ephemeral repositories.
  5→/// </summary>
  6→/// <remarks>
  7→/// This adapter stores all data in memory using a dictionary. Data is lost when the adapter
  8→/// is disposed or when the application terminates. Use this adapter for:
  9→/// <list type="bullet">
 10→/// <item>Unit and integration testing</item>
 11→/// <item>Temporary documents that don't require persistence</item>
 12→/// <item>Prototyping and development</item>
 13→/// </list>
 14→/// <para>
 15→/// This adapter is thread-safe and supports concurrent operations.
 16→/// </para>
 17→/// </remarks>
 18→[PublicAPI]
 19→public sealed class InMemoryStorageAdapter : IStorageAdapter, IDisposable
 20→{
 21→  readonly Dictionary<string, byte[]> _storage = [];
 22→  readonly SemaphoreSlim _lock = new(1, 1);
 23→  bool _isDisposed;
 24→  
 25→  
 26→  /// <summary>
 27→  /// Gets the number of keys currently stored.
 28→  /// </summary>
 29→  /// <remarks>
 30→  /// This property is useful for testing and debugging.
 31→  /// </remarks>
 32→  public int Count
 33→  {
 34→    get
 35→    {
 36→      ThrowIfDisposed();
 37→      return _storage.Count;
 38→    }
 39→  }
 40→  
 41→  
 42→  
 43→  /// <summary>
 44→  /// 
 45→  /// Disposes this storage adapter and clears all data.
 46→  /// </summary>
 47→  public void Dispose()
 48→  {
 49→    if(_isDisposed)
 50→      return;
 51→
 52→    _isDisposed = true;
 53→    _storage.Clear();
 54→    _lock.Dispose();
 55→  }
 56→
 57→  
 58→  public async Task<byte[]?> Load(StorageKey key)
 59→  {
 60→    ThrowIfDisposed();
 61→
 62→    await _lock.WaitAsync();
 63→    try
 64→    {
 65→      var keyString = key.ToDebugString();
 66→      if(!_storage.TryGetValue(keyString, out var data))
 67→        return null;
 68→
 69→      // Copy the data to ensure isolation
 70→      var copy = new byte[data.Length];
 71→      Array.Copy(data, copy, data.Length);
 72→      return copy;
 73→    }
 74→    finally
 75→    {
 76→      _lock.Release();
 77→    }
 78→  }
 79→
 80→  public async Task Save(StorageKey key, byte[] data)
 81→  {
 82→    ThrowIfDisposed();
 83→
 84→    if(data is null)
 85→      throw new ArgumentNullException(nameof(data));
 86→
 87→    await _lock.WaitAsync();
 88→    try
 89→    {
 90→      var keyString = key.ToDebugString();
 91→      // Copy the data to ensure isolation
 92→      var copy = new byte[data.Length];
 93→      Array.Copy(data, copy, data.Length);
 94→      _storage[keyString] = copy;
 95→    }
 96→    finally
 97→    {
 98→      _lock.Release();
 99→    }
100→  }
101→
102→  public async Task Remove(StorageKey key)
103→  {
104→    ThrowIfDisposed();
105→
106→    await _lock.WaitAsync();
107→    try
108→    {
109→      var keyString = key.ToDebugString();
110→      _storage.Remove(keyString);
111→    }
112→    finally
113→    {
114→      _lock.Release();
115→    }
116→  }
117→
118→  public async Task<IReadOnlyList<Chunk>> LoadRange(StorageKey keyPrefix)
119→  {
120→    ThrowIfDisposed();
121→
122→    await _lock.WaitAsync();
123→    try
124→    {
125→      var results = new List<Chunk>();
126→
127→      foreach(var kvp in _storage)
128→      {
129→        // Parse the key back to StorageKey
130→        var components = kvp.Key.Split('/');
131→        var storageKey = new StorageKey(components);
132→
133→        // Check if it matches the prefix
134→        if(storageKey.StartsWith(keyPrefix))
135→        {
136→          // Copy the data to ensure isolation
137→          var dataCopy = new byte[kvp.Value.Length];
138→          Array.Copy(kvp.Value, dataCopy, kvp.Value.Length);
139→          results.Add(new Chunk(storageKey, dataCopy));
140→        }
141→      }
142→
143→      return results;
144→    }
145→    finally
146→    {
147→      _lock.Release();
148→    }
149→  }
150→
151→  public async Task RemoveRange(StorageKey keyPrefix)
152→  {
153→    ThrowIfDisposed();
154→
155→    await _lock.WaitAsync();
156→    try
157→    {
158→      // Find all keys that match the prefix
159→      var keysToRemove = new List<string>();
160→
161→      foreach(var kvp in _storage)
162→      {
163→        var components = kvp.Key.Split('/');
164→        var storageKey = new StorageKey(components);
165→
166→        if(storageKey.StartsWith(keyPrefix))
167→        {
168→          keysToRemove.Add(kvp.Key);
169→        }
170→      }
171→
172→      // Remove them
173→      foreach(var key in keysToRemove)
174→      {
175→        _storage.Remove(key);
176→      }
177→    }
178→    finally
179→    {
180→      _lock.Release();
181→    }
182→  }
183→
184→  public async Task<IReadOnlyList<ChunkInfo>> GetChunkInfo(StorageKey keyPrefix)
185→  {
186→    ThrowIfDisposed();
187→
188→    await _lock.WaitAsync();
189→    try
190→    {
191→      var results = new List<ChunkInfo>();
192→
193→      foreach(var kvp in _storage)
194→      {
195→        var components = kvp.Key.Split('/');
196→        var storageKey = new StorageKey(components);
197→
198→        if(storageKey.StartsWith(keyPrefix))
199→        {
200→          results.Add(new ChunkInfo(storageKey, kvp.Value.Length));
201→        }
202→      }
203→
204→      return results;
205→    }
206→    finally
207→    {
208→      _lock.Release();
209→    }
210→  }
211→
212→  /// <summary>
213→  /// Clears all data from storage.
214→  /// </summary>
215→  /// <remarks>
216→  /// This method is useful for testing scenarios where you need to reset storage state.
217→  /// </remarks>
218→  public async Task Clear()
219→  {
220→    ThrowIfDisposed();
221→
222→    await _lock.WaitAsync();
223→    try
224→    {
225→      _storage.Clear();
226→    }
227→    finally
228→    {
229→      _lock.Release();
230→    }
231→  }
232→
233→  
234→  
235→  void ThrowIfDisposed()
236→  {
237→    if(_isDisposed)
238→      throw new ObjectDisposedException(nameof(InMemoryStorageAdapter));
239→  }
240→
241→}

