  6→/// <summary>
  7→/// File system storage adapter that persists data to local disk with in-memory caching.
  8→/// </summary>
  9→/// <remarks>
 10→/// <para>
 11→/// This adapter stores data in a hierarchical directory structure with sharding to prevent
 12→/// directory overflow. The first key component is split: first 2 chars become a directory,
 13→/// remaining chars become a subdirectory.
 14→/// </para>
 15→/// <para>
 16→/// Example: Key ["abc123", "snapshot", "hash"] → baseDir/ab/c123/snapshot/hash
 17→/// </para>
 18→/// <para>
 19→/// Data is cached in memory using MemoryCache for fast repeated reads.
 20→/// </para>
 21→/// </remarks>
 22→[PublicAPI]
 23→public sealed class FileSystemStorageAdapter : StorageAdapterBase, IDisposable
 24→{
 25→  readonly string _baseDirectory;
 26→  readonly IMemoryCache _cache;
 27→  readonly SemaphoreSlim _lock = new(1, 1);
 28→  readonly TimeSpan _cacheSlidingExpiration;
 29→  bool _disposed;
 30→
 31→
 32→  /// <summary>
 33→  /// Creates a new file system storage adapter.
 34→  /// </summary>
 35→  /// <param name="baseDirectory">Base directory for storage. Created if it doesn't exist.</param>
 36→  /// <param name="options">Optional configuration. If null, uses default settings.</param>
 37→  public FileSystemStorageAdapter(string baseDirectory, FileSystemStorageOptions? options = null)
 38→  {
 39→    if(string.IsNullOrWhiteSpace(baseDirectory))
 40→      throw new ArgumentException("Base directory cannot be null or whitespace", nameof(baseDirectory));
 41→
 42→    options ??= new FileSystemStorageOptions();
 43→
 44→    _baseDirectory = Path.GetFullPath(baseDirectory);
 45→    _cacheSlidingExpiration = options.CacheSlidingExpiration;
 46→
 47→    // Initialize cache with size limit
 48→    _cache = new MemoryCache(new MemoryCacheOptions
 49→    {
 50→      SizeLimit = options.CacheSizeLimit
 51→    });
 52→
 53→    // Create base directory if it doesn't exist
 54→    Directory.CreateDirectory(_baseDirectory);
 55→  }
 56→
 57→
 58→  /// <summary>
 59→  /// Loads data for a storage key. Checks cache first, then disk.
 60→  /// </summary>
 61→  public override async Task<byte[]?> Load(StorageKey key)
 62→  {
 63→    ThrowIfDisposed();
 64→
 65→    var cacheKey = GetCacheKey(key);
 66→
 67→    // Try cache first
 68→    if(_cache.TryGetValue(cacheKey, out byte[]? cachedData))
 69→    {
 70→      return cachedData;
 71→    }
 72→
 73→    // Load from disk
 74→    var filePath = GetFilePath(key);
 75→
 76→    await _lock.WaitAsync();
 77→    try
 78→    {
 79→      if(!File.Exists(filePath))
 80→        return null;
 81→
 82→      var data = await File.ReadAllBytesAsync(filePath);
 83→
 84→      // Store in cache with sliding expiration
 85→      var cacheOptions = new MemoryCacheEntryOptions()
 86→        .SetSize(data.Length)
 87→        .SetSlidingExpiration(_cacheSlidingExpiration);
 88→
 89→      _cache.Set(cacheKey, data, cacheOptions);
 90→
 91→      return data;
 92→    }
 93→    catch(FileNotFoundException)
 94→    {
 95→      return null;
 96→    }
 97→    catch(DirectoryNotFoundException)
 98→    {
 99→      return null;
100→    }
101→    finally
102→    {
103→      _lock.Release();
104→    }
105→  }
106→
107→  /// <summary>
108→  /// Saves data to storage. Updates cache and writes to disk.
109→  /// </summary>
110→  public override async Task Save(StorageKey key, byte[] data)
111→  {
112→    ThrowIfDisposed();
113→
114→    if(data == null)
115→      throw new ArgumentNullException(nameof(data));
116→
117→    var cacheKey = GetCacheKey(key);
118→    var filePath = GetFilePath(key);
119→
120→    await _lock.WaitAsync();
121→    try
122→    {
123→      // Create directory structure
124→      var directory = Path.GetDirectoryName(filePath);
125→      if(!string.IsNullOrEmpty(directory))
126→      {
127→        Directory.CreateDirectory(directory);
128→      }
129→
130→      // Write to disk
131→      await File.WriteAllBytesAsync(filePath, data);
132→
133→      // Update cache
134→      var cacheOptions = new MemoryCacheEntryOptions()
135→        .SetSize(data.Length)
136→        .SetSlidingExpiration(_cacheSlidingExpiration);
137→
138→      _cache.Set(cacheKey, data, cacheOptions);
139→    }
140→    finally
141→    {
142→      _lock.Release();
143→    }
144→  }
145→
146→  /// <summary>
147→  /// Removes data for a storage key. Removes from cache and deletes file.
148→  /// </summary>
149→  public override async Task Remove(StorageKey key)
150→  {

