  8→/// Maintains per-peer sync state and implements the Automerge sync protocol.
  9→/// </summary>
 10→internal sealed class DocSynchronizer : IDisposable
 11→{
 12→  readonly string _documentId;
 13→  readonly DocumentId _documentIdValue;
 14→  readonly Func<AutomergeDocument?> _getDocument;
 15→  readonly Action<AutomergeDocument> _updateDocument;
 16→  readonly Func<PeerId, PeerMetadata?> _getPeerMetadata;
 17→
 18→  readonly Dictionary<PeerId, AutomergeSyncState> _syncStates = [];
 19→  readonly Dictionary<PeerId, PeerDocumentStatus> _peerStatuses = [];
 20→  readonly HashSet<PeerId> _activePeers = [];
 21→  readonly SemaphoreSlim _lock = new(1, 1);
 22→
 23→  int _messagesSent;
 24→  int _messagesReceived;
 25→  bool _disposed;
 26→
 27→  /// <summary>
 28→  /// Event fired when a message should be sent to a peer.
 29→  /// </summary>
 30→  public event EventHandler<SyncMessageEventArgs>? MessageToSend;
 31→
 32→  /// <summary>
 33→  /// Event fired when sync state changes (for persistence).
 34→  /// </summary>
 35→  public event EventHandler<SyncStateChangedEventArgs>? SyncStateChanged;
 36→
 37→  /// <summary>
 38→  /// Event fired when sync metrics are updated.
 39→  /// </summary>
 40→  public event EventHandler<SyncMetricsEventArgs>? MetricsUpdated;
 41→
 42→  /// <summary>
 43→  /// Creates a new DocSynchronizer for a specific document.
 44→  /// </summary>
 45→  /// <param name="documentId">The document ID being synchronized</param>
 46→  /// <param name="getDocument">Callback to retrieve the current document</param>
 47→  /// <param name="updateDocument">Callback to update the document after receiving changes</param>
 48→  /// <param name="getPeerMetadata">Callback to retrieve peer metadata</param>
 49→  public DocSynchronizer(
 50→    string documentId,
 51→    Func<AutomergeDocument?> getDocument,
 52→    Action<AutomergeDocument> updateDocument,
 53→    Func<PeerId, PeerMetadata?> getPeerMetadata)
 54→  {
 55→    _documentId = documentId ?? throw new ArgumentNullException(nameof(documentId));
 56→    _documentIdValue = DocumentId.Parse(documentId);
 57→    _getDocument = getDocument ?? throw new ArgumentNullException(nameof(getDocument));
 58→    _updateDocument = updateDocument ?? throw new ArgumentNullException(nameof(updateDocument));
 59→    _getPeerMetadata = getPeerMetadata ?? throw new ArgumentNullException(nameof(getPeerMetadata));
 60→  }
 61→
 62→  /// <summary>
 63→  /// Begins synchronization with a peer. Sends initial sync message.
 64→  /// </summary>
 65→  public void BeginSync(PeerId peerId)
 66→  {
 67→    ThrowIfDisposed();
 68→
 69→    Console.WriteLine($"[DocSync] BeginSync for document {_documentId} with peer {peerId}");
 70→
 71→    // Collect events to fire after releasing lock
 72→    var deferredEvents = new List<Action>();
 73→
 74→    _lock.Wait();
 75→    try
 76→    {
 77→      if(_activePeers.Contains(peerId))
 78→      {
 79→        Console.WriteLine($"[DocSync] Peer {peerId} already syncing document {_documentId}, skipping");
 80→        return;
 81→      }
 82→
 83→      _activePeers.Add(peerId);
 84→
 85→      // Initialize status as unknown
 86→      if(!_peerStatuses.ContainsKey(peerId))
 87→      {
 88→        _peerStatuses[peerId] = PeerDocumentStatus.Unknown;
 89→      }
 90→
 91→      Console.WriteLine($"[DocSync] Sending initial sync message for document {_documentId} to peer {peerId}");
 92→      // Send initial sync message
 93→      SendSyncMessage(peerId, deferredEvents);
 94→    }
 95→    finally
 96→    {
 97→      _lock.Release();
 98→    }
 99→
100→    // Fire all deferred events after releasing the lock
101→    foreach(var eventAction in deferredEvents)
102→    {
103→      eventAction();
104→    }
105→  }
106→
107→  /// <summary>
108→  /// Ends synchronization with a peer. Cleans up state.
109→  /// </summary>
110→  public void EndSync(PeerId peerId)
111→  {
112→    ThrowIfDisposed();
113→
114→    _lock.Wait();
115→    try
116→    {
117→      _activePeers.Remove(peerId);
118→
119→      // Dispose sync state before removing
120→      if(_syncStates.TryGetValue(peerId, out var state))
121→      {
122→        state.Dispose();
123→      }
124→
125→      _syncStates.Remove(peerId);
126→      _peerStatuses.Remove(peerId);
127→    }
128→    finally
129→    {
130→      _lock.Release();
131→    }
132→  }
133→
134→  /// <summary>
135→  /// Checks if we're actively syncing with a peer.
136→  /// </summary>
137→  public bool HasPeer(PeerId peerId)
138→  {
139→    ThrowIfDisposed();
140→
141→    _lock.Wait();
142→    try
143→    {
144→      return _activePeers.Contains(peerId);
145→    }
146→    finally
147→    {
148→      _lock.Release();
149→    }
150→  }
