422→static void DisplayDocumentState(string owner, AutomergeDocument doc)
423→{
424→    var json = doc.HydrateJson();
425→    using var parsed = JsonDocument.Parse(json);
426→    var root = parsed.RootElement;
427→
428→    Console.WriteLine($"\n  {owner}'s Document State:");
429→
430→    if (root.TryGetProperty("project_name", out var projectName))
431→    {
432→        Console.WriteLine($"    Project: {projectName.GetString()}");
433→    }
434→
435→    if (root.TryGetProperty("status", out var status))
436→    {
437→        Console.WriteLine($"    Status: {status.GetString()}");
438→    }
439→
440→    if (root.TryGetProperty("total_views", out var views))
441→    {
442→        if (views.ValueKind == JsonValueKind.Number)
443→        {
444→            Console.WriteLine($"    Total Views: {views.GetInt64()}");
445→        }
446→        else
447→        {
448→            Console.WriteLine($"    Total Views: {views.ValueKind}");
449→        }
450→    }
451→
452→    if (root.TryGetProperty("tasks", out var tasks))
453→    {
454→        var taskCount = tasks.GetArrayLength();
455→        Console.WriteLine($"    Tasks: {taskCount}");
456→
457→        for (int i = 0; i < Math.Min(taskCount, 5); i++)
458→        {
459→            var task = tasks[i];
460→            var title = task.TryGetProperty("title", out var t) ? t.GetString() : "Untitled";
461→            var completed = task.TryGetProperty("completed", out var c) && c.GetBoolean();
462→            var completedMark = completed ? "✓" : " ";
463→            Console.WriteLine($"      [{completedMark}] {title}");
464→        }
465→    }
466→
467→    Console.WriteLine($"    Pending Ops: {doc.PendingOperations}");
468→    Console.WriteLine($"    Heads: {doc.GetHeads().Count}");
469→}
