486→static void VerifyConvergence(AutomergeDocument doc1, AutomergeDocument doc2, AutomergeDocument doc3)
487→{
488→    var json1 = doc1.HydrateJson();
489→    var json2 = doc2.HydrateJson();
490→    var json3 = doc3.HydrateJson();
491→
492→    using var parsed1 = JsonDocument.Parse(json1);
493→    using var parsed2 = JsonDocument.Parse(json2);
494→    using var parsed3 = JsonDocument.Parse(json3);
495→
496→    var keys1 = parsed1.RootElement.EnumerateObject().Select(p => p.Name).OrderBy(k => k).ToList();
497→    var keys2 = parsed2.RootElement.EnumerateObject().Select(p => p.Name).OrderBy(k => k).ToList();
498→    var keys3 = parsed3.RootElement.EnumerateObject().Select(p => p.Name).OrderBy(k => k).ToList();
499→
500→    var keysMatch = keys1.SequenceEqual(keys2) && keys2.SequenceEqual(keys3);
501→
502→    Console.WriteLine($"\n  Convergence Verification:");
503→    Console.WriteLine($"    Keys Match: {(keysMatch ? "✓ Yes" : "✗ No")}");
504→    Console.WriteLine($"    Common Keys: {string.Join(", ", keys1)}");
505→
506→    if (parsed1.RootElement.TryGetProperty("tasks", out var tasks1) &&
507→        parsed2.RootElement.TryGetProperty("tasks", out var tasks2) &&
508→        parsed3.RootElement.TryGetProperty("tasks", out var tasks3))
509→    {
510→        var taskCount1 = tasks1.GetArrayLength();
511→        var taskCount2 = tasks2.GetArrayLength();
512→        var taskCount3 = tasks3.GetArrayLength();
513→
514→        var tasksMatch = taskCount1 == taskCount2 && taskCount2 == taskCount3;
515→        Console.WriteLine($"    Task Counts Match: {(tasksMatch ? "✓ Yes" : "✗ No")} ({taskCount1}, {taskCount2}, {taskCount3})");
516→    }
517→}
